const candidateFinalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))

	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts) + 6
	if r.attemptLimit < 10 {
		r.attemptLimit = 10
	}
	if r.attemptLimit > 32 {
		r.attemptLimit = 32
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if amt <= 0 || capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.050)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.033))
	p := 0.47*lowMode + 0.53*highMode

	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity ||
		r.policyBlocked[edge.key] {

		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case failure.count >= 3 && ratio > 0.38:
			return 0
		case failure.count >= 2 && ratio > 0.55:
			return 0
		case ratio > 0.78:
			return 0
		case ratio > 0.64:
			retryScale = 0.16
		case ratio > 0.50:
			retryScale = 0.34
		case ratio > 0.36:
			retryScale = 0.58
		default:
			retryScale = 0.82
		}
		if failure.count >= 2 {
			retryScale *= 0.72
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.003

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		evidence := 0.995 - 0.991*position
		p = 0.10*p + 0.90*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.20 {
			scale := 1 - 0.90*(ratio-0.20)/0.80
			if scale < 0.08 {
				scale = 0.08
			}
			p *= scale
		}

	case belief.lowerOK > 0:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		if distance > 0 {
			boost := 0.62 * math.Exp(-distance/0.18)
			p += boost * (1 - p)
		}
	}

	if belief.estimate > 0 {
		scale := 0.07 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateP := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.15
		evidenceCount := belief.successes + belief.failures
		if evidenceCount >= 2 {
			weight = 0.23
		}
		if evidenceCount >= 4 {
			weight = 0.31
		}
		p = (1-weight)*p + weight*estimateP
	}

	p *= retryScale
	switch {
	case p < 0.001:
		return 0.001
	case p > 0.997:
		return 0.997
	default:
		return p
	}
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	totalP := r.liquidityProbability(edge, reserved+amt)
	if totalP <= 0 {
		return 0
	}
	if reserved == 0 {
		return totalP
	}

	baseP := r.liquidityProbability(edge, reserved)
	if baseP <= 0 {
		return 0
	}

	p := totalP / baseP
	switch {
	case p < 0.001:
		return 0.001
	case p > 0.997:
		return 0.997
	default:
		return p
	}
}

type candidatePathLabel struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	edge     *candidateEdge
	next     *candidatePathLabel
	hops     int
	active   bool
	index    int
}

type candidatePathQueue []*candidatePathLabel

func (q candidatePathQueue) Len() int {
	return len(q)
}

func (q candidatePathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidatePathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidatePathQueue) Push(value any) {
	label := value.(*candidatePathLabel)
	label.index = len(*q)
	*q = append(*q, label)
}

func (q *candidatePathQueue) Pop() any {
	old := *q
	last := len(old) - 1
	label := old[last]
	*q = old[:last]
	return label
}

func candidatePathContains(label *candidatePathLabel,
	node route.Vertex) bool {

	for current := label; current != nil; current = current.next {
		if current.node == node {
			return true
		}
	}
	return false
}

func candidateInsertLabel(labels map[route.Vertex][]*candidatePathLabel,
	label *candidatePathLabel) bool {

	current := labels[label.node]
	for _, old := range current {
		if old.active && old.score <= label.score &&
			old.required <= label.required {

			return false
		}
	}

	kept := current[:0]
	for _, old := range current {
		if old.active && label.score <= old.score &&
			label.required <= old.required {

			old.active = false
			continue
		}
		if old.active {
			kept = append(kept, old)
		}
	}
	kept = append(kept, label)

	if len(kept) > 3 {
		sort.Slice(kept, func(i, j int) bool {
			left := kept[i].score +
				float64(kept[i].required)/16_000_000
			right := kept[j].score +
				float64(kept[j].required)/16_000_000
			return left < right
		})
		for _, old := range kept[3:] {
			old.active = false
		}
		kept = kept[:3]
	}

	labels[label.node] = kept
	return label.active
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 780_000.0
		hopPenalty = 22_000.0
		maxHops    = 30
		maxExpand  = 14000
	)

	target := &candidatePathLabel{
		node:     r.spec.Target,
		required: amt,
		active:   true,
	}
	labels := map[route.Vertex][]*candidatePathLabel{
		r.spec.Target: {target},
	}
	queue := &candidatePathQueue{}
	heap.Push(queue, target)

	var sourceLabel *candidatePathLabel
	expanded := 0

	for queue.Len() != 0 && expanded < maxExpand {
		item := heap.Pop(queue).(*candidatePathLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}
		if item.hops >= maxHops {
			continue
		}

		expanded++
		for _, edge := range r.incomingEdges[item.node] {
			if candidatePathContains(item, edge.key.from) {
				continue
			}

			amountOverEdge := item.required
			p := r.probability(edge, amountOverEdge)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			required := amountOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.suspect[edge.key]) * 310_000
			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}

			label := &candidatePathLabel{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: required,
				logProb:  item.logProb + math.Log(p),
				edge:     edge,
				next:     item,
				hops:     item.hops + 1,
				active:   true,
			}
			if candidateInsertLabel(labels, label) {
				heap.Push(queue, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, sourceLabel.hops)
	for current := sourceLabel; current != nil && current.edge != nil;
		current = current.next {

		path = append(path, current.edge)
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLabel.logProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	node := r.source
	for _, edge := range path {
		if edge.key.from != node {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, errors.New("path does not reach target")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(candidateFinalCltvDelta)
		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, index int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return 0, false
	}
	if index == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[index-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	copy := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		copy[key] = amount
	}
	return copy
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	if rt == nil {
		return
	}
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	for _, rt := range r.held[len(r.held)-count:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	avg := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	values := make([]lnwire.MilliSatoshi, 0, 12)
	seen := make(map[lnwire.MilliSatoshi]bool)

	for _, value := range []lnwire.MilliSatoshi{
		avg * 2 / 3,
		avg * 5 / 6,
		avg,
		avg * 6 / 5,
		avg * 3 / 2,
	} {
		candidateAddAmount(
			&values, seen, value, minimum, maximum,
		)
	}

	if r.lastFailedShard > 0 {
		for _, value := range []lnwire.MilliSatoshi{
			r.lastFailedShard * 2 / 5,
			r.lastFailedShard / 2,
			r.lastFailedShard * 3 / 5,
		} {
			candidateAddAmount(
				&values, seen, value, minimum, maximum,
			)
		}
	}

	for key, belief := range r.beliefs {
		reserved := r.reserved[key]
		if belief.lowerOK > reserved {
			candidateAddAmount(
				&values, seen,
				(belief.lowerOK-reserved)*19/20,
				minimum, maximum,
			)
		}
		if belief.upperFail > reserved {
			candidateAddAmount(
				&values, seen,
				(belief.upperFail-reserved)*9/20,
				minimum, maximum,
			)
		}
		if belief.estimate > reserved {
			candidateAddAmount(
				&values, seen,
				(belief.estimate-reserved)*4/5,
				minimum, maximum,
			)
		}
	}

	sort.Slice(values, func(i, j int) bool {
		left := math.Abs(math.Log(
			float64(values[i]) / float64(avg),
		))
		right := math.Abs(math.Log(
			float64(values[j]) / float64(avg),
		))
		if left == right {
			return values[i] > values[j]
		}
		return left < right
	})
	if len(values) > 7 {
		values = values[:7]
	}

	return values
}

func candidateSharedPenalty(routes []*route.Route) map[candidateEdgeKey]float64 {
	penalties := make(map[candidateEdgeKey]float64)
	for _, rt := range routes {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			if key.from == rt.SourcePubKey {
				penalties[key] += 100_000
			} else {
				penalties[key] += 520_000
			}
		}
	}
	return penalties
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations, base map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	score := 0.0
	for key, total := range reservations {
		old := base[key]
		if total <= old {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, total)
		if p <= 0 {
			return math.Inf(-1)
		}
		if old > 0 {
			oldP := r.liquidityProbability(edge, old)
			if oldP <= 0 {
				return math.Inf(-1)
			}
			p /= oldP
		}

		if p < 0.001 {
			p = 0.001
		}
		if p > 0.999 {
			p = 0.999
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)
	for _, rt := range routes {
		finalAmount := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmount {
			fees += rt.TotalAmount - finalAmount
		}
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 30_000_000
	if len(routes) > 1 {
		score -= 0.018 * float64(len(routes)-1)
	}
	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.025 * float64(count-1)
		}
	}

	return score
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	shapePenalty float64
	score        float64
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 2

	base := candidateCopyReservations(r.reserved)
	saved := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = saved
	}()

	targetAverage := float64(total) / float64(parts)
	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(base),
	}}

	for depth := 0; depth < parts; depth++ {
		slots := parts - depth
		expanded := make([]candidatePlanState, 0, beamWidth*7)

		for _, state := range states {
			r.reserved = candidateCopyReservations(
				state.reservations,
			)
			sizes := r.shardSizes(state.remaining, slots)
			penalty := candidateSharedPenalty(state.routes)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				remaining := state.remaining - size
				if slots == 1 && remaining != 0 {
					continue
				}
				if slots > 1 &&
					remaining < lnwire.MilliSatoshi(slots-1) {

					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				rt, _, err := r.findRoute(size, penalty)
				if err != nil {
					continue
				}

				reservations := candidateCopyReservations(
					state.reservations,
				)
				candidateReserveInto(reservations, rt)

				routes := append(
					append([]*route.Route(nil), state.routes...),
					rt,
				)
				shape := state.shapePenalty
				ratio := float64(size) / targetAverage
				if ratio > 0 {
					shape += 0.10 * math.Abs(math.Log(ratio))
				}

				next := candidatePlanState{
					remaining:    remaining,
					routes:       routes,
					reservations: reservations,
					shapePenalty: shape,
				}
				next.score = r.planScore(
					routes, reservations, base,
				) - shape
				if math.IsInf(next.score, -1) {
					continue
				}
				expanded = append(expanded, next)
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.Slice(expanded, func(i, j int) bool {
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	for _, state := range states {
		if state.remaining == 0 {
			score := r.planScore(
				state.routes, state.reservations, base,
			)
			return state.routes, score, true
		}
	}

	return nil, 0, false
}

func candidatePartCounts(maxParts int) []int {
	if maxParts < 2 {
		return nil
	}

	seen := make(map[int]bool)
	counts := make([]int, 0, 4)
	add := func(count int) {
		if count >= 2 && count <= maxParts && !seen[count] {
			seen[count] = true
			counts = append(counts, count)
		}
	}

	add(2)
	add(3)
	add(4)

	largest := maxParts
	if largest > 8 {
		largest = 8
	}
	add(largest)

	sort.Ints(counts)
	return counts
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	fullRoute, fullLogProb, fullErr := r.findRoute(total, nil)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{fullRoute}, nil
	}

	if fullErr == nil && fullLogProb >= math.Log(0.982) &&
		r.lastFailedShard == 0 {

		return []*route.Route{fullRoute}, nil
	}

	base := candidateCopyReservations(r.reserved)
	var best []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(base)
		candidateReserveInto(reservations, fullRoute)
		best = []*route.Route{fullRoute}
		bestScore = r.planScore(best, reservations, base)
	}

	for _, count := range candidatePartCounts(int(parts)) {
		plan, score, ok := r.planWithParts(total, count)
		if !ok {
			continue
		}
		if best == nil || score > bestScore {
			best = plan
			bestScore = score
		}
	}

	if best == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{fullRoute}, nil
	}

	return best, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) != 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt {
			r.planned = r.planned[1:]
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}
	if len(plan) == 0 {
		return nil, errors.New("empty route plan")
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil && edge.capacity > 0 {
		ratio := float64(amt) / float64(edge.capacity)
		switch {
		case ratio >= 0.08:
			estimate = edge.capacity * 7 / 8
		case ratio >= 0.035:
			estimate = edge.capacity * 3 / 4
		default:
			estimate = amt * 2
		}
		if estimate > edge.capacity {
			estimate = edge.capacity
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt / 3
	if edge := r.edges[key]; edge != nil {
		lowEstimate := edge.capacity / 18
		if estimate > lowEstimate {
			estimate = lowEstimate
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	if rt == nil {
		return
	}
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}

			r.learnSuccess(key, amount+r.reserved[key])
			if r.suspect[key] > 0 {
				r.suspect[key]--
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failureIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amount, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amount + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 4
		r.lastFailedShard = candidateFinalAmount(rt)

	default:
		r.suspect[key] += 3
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 10
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 48 {
		r.attemptLimit = 48
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)

	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.034))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if amt <= 0 {
		return 0.995
	}
	if amt > edge.capacity {
		return 0
	}

	p := candidatePrior(amt, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && amt <= belief.lowerOK {
		return 0.995
	}

	if belief.upperFail > 0 && amt >= belief.upperFail {
		return 0.008
	}

	if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK &&
		amt > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(amt-belief.lowerOK) / width
		evidence := 0.99 - 0.98*position
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(amt) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.96*(ratio-0.45)/0.55
			if scale < 0.04 {
				scale = 0.04
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && amt > belief.lowerOK {
		distance := float64(amt-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.5 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.1 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}

		point := 1 / (1 + math.Exp(
			(float64(amt)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*point
	}

	if p < 0.003 {
		return 0.003
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) observedSurvival(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	p := r.liquidityProbability(edge, amt)
	failure, failed := r.currentFails[edge.key]
	if !failed || failure.upper == 0 {
		return p
	}
	if amt >= failure.upper {
		return 0
	}

	failSurvival := r.liquidityProbability(edge, failure.upper)
	denominator := 1 - failSurvival
	if denominator < 0.01 {
		denominator = 0.01
	}

	conditional := (p - failSurvival) / denominator
	if conditional < 0.002 {
		conditional = 0.002
	}
	if conditional > 0.995 {
		conditional = 0.995
	}

	return conditional
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	reserved := r.reserved[edge.key]
	total := amt + reserved
	if total > edge.capacity {
		return 0
	}

	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	totalProbability := r.observedSurvival(edge, total)
	if totalProbability <= 0 {
		return 0
	}

	if reserved == 0 {
		return totalProbability
	}

	reservedProbability := r.observedSurvival(edge, reserved)
	if reservedProbability <= 0 {
		return 0
	}

	conditional := totalProbability / reservedProbability
	if conditional < 0.002 {
		return 0.002
	}
	if conditional > 0.995 {
		return 0.995
	}
	return conditional
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidateCappedCount(value, cap uint32) uint32 {
	if value > cap {
		return cap
	}
	return value
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 500_000.0
		hopPenalty = 3_500.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProbability float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProbability = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOverEdge := item.required
			p := r.probability(edge, amountOverEdge)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			sendingAmount := amountOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			uses := candidateCappedCount(r.edgeUses[edge.key], 5)
			suspect := candidateCappedCount(r.suspect[edge.key], 4)

			edgeScore += float64(uses) * 12_000
			edgeScore += float64(suspect) * 115_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 85_000
			}

			score := item.score + edgeScore
			oldScore, found := bestScore[edge.key.from]
			if found && score >= oldScore {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge

			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sendingAmount,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amountOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amountOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amountOver[i] = amountOver[i+1] +
			forwardingEdge.fee(amountOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amountOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amountOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}

	if channelIndex == 0 {
		return rt.TotalAmount, true
	}

	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amount := range src {
		dst[key] = amount
	}
	return dst
}

func candidateReserveRoute(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveRoute(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool,
	value, maximum lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > maximum {
		value = maximum
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidateScaledAmount(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if denominator <= 0 {
		return value
	}
	return value * lnwire.MilliSatoshi(numerator) /
		lnwire.MilliSatoshi(denominator)
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	ratios := [][2]int64{
		{1, 4},
		{2, 5},
		{1, 2},
		{3, 5},
		{3, 4},
		{1, 1},
		{5, 4},
		{3, 2},
		{7, 4},
		{2, 1},
		{5, 2},
		{3, 1},
	}

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	for _, ratio := range ratios {
		candidateAddAmount(
			&sizes, seen,
			candidateScaledAmount(base, ratio[0], ratio[1]),
			remaining,
		)
	}

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/3, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/12, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
	}

	candidateAddAmount(&sizes, seen, remaining, remaining)

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] > sizes[j]
	})

	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	searchScore  float64
	jointScore   float64
}

func candidatePlanBetter(a, b *candidatePlanState) bool {
	if a.remaining == 0 && b.remaining != 0 {
		return true
	}
	if a.remaining != 0 && b.remaining == 0 {
		return false
	}
	if a.searchScore != b.searchScore {
		return a.searchScore > b.searchScore
	}
	return a.remaining < b.remaining
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32, sizeBias float64) ([]*route.Route, float64, bool) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []*candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var completed []*candidatePlanState

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		var nextStates []*candidatePlanState

		for _, state := range states {
			if state.remaining == 0 {
				completed = append(completed, state)
				continue
			}
			if state.slots == 0 {
				continue
			}

			base := (state.remaining +
				lnwire.MilliSatoshi(state.slots) - 1) /
				lnwire.MilliSatoshi(state.slots)

			sizes := r.shardSizes(state.remaining, state.slots)
			for _, size := range sizes {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				rt, logProbability, err := r.findRoute(size)
				if err != nil {
					continue
				}

				fees := rt.TotalAmount - size
				sizeReward := math.Log(
					float64(size) / float64(base),
				)

				reservations := candidateCopyReservations(
					state.reservations,
				)
				candidateReserveRoute(reservations, rt)

				routes := make(
					[]*route.Route, len(state.routes), len(state.routes)+1,
				)
				copy(routes, state.routes)
				routes = append(routes, rt)

				jointIncrement := logProbability -
					float64(fees)/4_000_000 - 0.02

				next := &candidatePlanState{
					remaining: state.remaining - size,
					slots:     state.slots - 1,
					routes:    routes,
					reservations: reservations,
					jointScore: state.jointScore +
						jointIncrement,
					searchScore: state.searchScore +
						jointIncrement + sizeBias*sizeReward,
				}

				if next.remaining == 0 {
					completed = append(completed, next)
				} else {
					nextStates = append(nextStates, next)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			return candidatePlanBetter(nextStates[i], nextStates[j])
		})

		const beamWidth = 10
		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if len(completed) == 0 {
		return nil, 0, false
	}

	best := completed[0]
	for _, state := range completed[1:] {
		if state.jointScore > best.jointScore {
			best = state
		}
	}

	return best.routes, best.jointScore, true
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	sizes := r.shardSizes(total, parts)
	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range sizes {
		rt, logProbability, err := r.findRoute(size)
		if err != nil {
			continue
		}

		fees := rt.TotalAmount - size
		progress := math.Log1p(float64(size)) -
			math.Log1p(float64(total))

		utility := logProbability + 0.75*progress -
			float64(fees)/4_000_000

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}
	return bestRoute, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32, inFlight uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	if inFlight == 0 && r.lastFailedShard == 0 {
		full, logProbability, err := r.findRoute(total)
		if err == nil && logProbability >= math.Log(0.3) {
			return []*route.Route{full}, nil
		}
	}

	biases := []float64{0.18, 0.38, 0.62, 0.9}
	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	for _, bias := range biases {
		plan, score, ok := r.planBeam(total, parts, bias)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan != nil {
		return bestPlan, nil
	}

	rt, err := r.fallbackShard(total, parts)
	if err != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)

		if finalAmount > 0 && finalAmount <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}

		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft, inFlightHtlcs)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++

	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]

	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]

	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 2 / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}

			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}

			r.learnSuccess(key, amount+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passedEdges := failureIndex
	if passedEdges > len(rt.Hops) {
		passedEdges = len(rt.Hops)
	}

	for i := 0; i < passedEdges; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	amountOver, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amountOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*10 + 24
	if r.attemptLimit < 48 {
		r.attemptLimit = 48
	}
	if r.attemptLimit > 96 {
		r.attemptLimit = 96
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) retryCeiling(
	failure candidateCurrentFailure) lnwire.MilliSatoshi {

	if failure.upper <= 1 {
		return 0
	}

	numerator := lnwire.MilliSatoshi(11)
	denominator := lnwire.MilliSatoshi(16)
	switch {
	case failure.count >= 5:
		numerator = 1
		denominator = 2
	case failure.count >= 3:
		numerator = 9
		denominator = 16
	case failure.count >= 2:
		numerator = 5
		denominator = 8
	}

	ceiling := failure.upper * numerator / denominator
	if ceiling >= failure.upper {
		ceiling = failure.upper - 1
	}
	return ceiling
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	if amt <= 0 || reserved > edge.capacity ||
		amt > edge.capacity-reserved {

		return 0
	}
	total := amt + reserved

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if total >= failure.upper {
			return 0
		}
		ceiling := r.retryCeiling(failure)
		if ceiling == 0 || total > ceiling {
			return 0
		}

		retryScale = 0.48 /
			(1 + 0.16*float64(failure.count-1))
		if retryScale < 0.16 {
			retryScale = 0.16
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || reserved > balance || amt > balance-reserved {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*pos
		p = 0.18*p + 0.82*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.94*(ratio-0.45)/0.55
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.50 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.11 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.68*p + 0.32*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 420_000.0
		hopPenalty = 900.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 18_000
			edgeScore += float64(r.suspect[edge.key]) * 230_000

			if reserved := r.reserved[edge.key]; reserved > 0 {
				if edge.key.from == r.source {
					edgeScore += 110_000
				} else {
					edgeScore += 470_000
				}
				util := float64(reserved) /
					float64(edge.capacity)
				edgeScore += 180_000 * util
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base/2, remaining)
	candidateAddAmount(&sizes, seen, base*2/3, remaining)
	candidateAddAmount(&sizes, seen, base*3/4, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, remaining/3, remaining)
	candidateAddAmount(&sizes, seen, remaining/2, remaining)
	candidateAddAmount(&sizes, seen, remaining*2/3, remaining)
	candidateAddAmount(&sizes, seen, remaining*3/4, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*9/16, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
	}

	for _, failure := range r.currentFails {
		if failure.upper == 0 {
			continue
		}
		ceiling := r.retryCeiling(failure)
		candidateAddAmount(&sizes, seen, ceiling/2, remaining)
		candidateAddAmount(
			&sizes, seen, ceiling*3/4, remaining,
		)
		candidateAddAmount(&sizes, seen, ceiling, remaining)
	}

	return sizes
}

func (r *candidateRouter) routeShardHint(rt *route.Route,
	max lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 {
		return 0
	}

	hint := max
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}
		edge := r.edges[key]
		if edge == nil {
			return 0
		}
		over, ok := candidateRouteAmount(rt, i)
		if !ok || over <= 0 {
			return 0
		}

		reserved := r.reserved[key]
		totalTarget := edge.capacity * 13 / 16

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok {
				return 0
			}
			totalTarget = balance
		} else if belief, ok := r.beliefs[key]; ok {
			switch {
			case belief.lowerOK > 0 &&
				belief.upperFail > belief.lowerOK:

				totalTarget = belief.lowerOK +
					(belief.upperFail-belief.lowerOK)*7/16

			case belief.upperFail > 0:
				totalTarget = belief.upperFail * 9 / 16

			case belief.lowerOK > 0:
				target := edge.capacity * 13 / 16
				if belief.lowerOK > target {
					target = belief.lowerOK
				}
				totalTarget = target
			}

			if belief.estimate > 0 &&
				belief.estimate < totalTarget {

				totalTarget = (totalTarget + belief.estimate) / 2
			}
		}

		if failure, ok := r.currentFails[key]; ok {
			ceiling := r.retryCeiling(failure)
			if ceiling < totalTarget {
				totalTarget = ceiling
			}
		}

		if totalTarget > edge.capacity {
			totalTarget = edge.capacity
		}
		if reserved >= totalTarget {
			return 0
		}

		allowed := totalTarget - reserved
		if edge.maxHTLC > 0 && edge.maxHTLC < allowed {
			allowed = edge.maxHTLC
		}
		if allowed < edge.minHTLC {
			return 0
		}

		scaled := lnwire.MilliSatoshi(
			float64(finalAmt) * float64(allowed) /
				float64(over),
		)
		if scaled < hint {
			hint = scaled
		}
	}

	if hint < 1 {
		return 0
	}
	if hint > max {
		return max
	}
	return hint
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	beam := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var complete []candidatePlanState
	const (
		beamWidth    = 36
		maxSizeTests = 40
	)

	for depth := uint32(0); depth < parts && len(beam) > 0; depth++ {
		var expanded []candidatePlanState

		for _, state := range beam {
			sizes := r.planSizes(state.remaining, state.slots)
			sizeSeen := make(map[lnwire.MilliSatoshi]bool)
			for _, size := range sizes {
				sizeSeen[size] = true
			}

			for sizeIndex := 0; sizeIndex < len(sizes) &&
				sizeIndex < maxSizeTests; sizeIndex++ {

				size := sizes[sizeIndex]
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				rt, logProb, err := r.findRoute(size)
				if err != nil {
					continue
				}

				hint := r.routeShardHint(rt, state.remaining)
				if hint > 0 {
					candidateAddAmount(
						&sizes, sizeSeen, hint*3/4,
						state.remaining,
					)
					candidateAddAmount(
						&sizes, sizeSeen, hint,
						state.remaining,
					)
					candidateAddAmount(
						&sizes, sizeSeen, hint*9/8,
						state.remaining,
					)
				}

				fees := rt.TotalAmount - size
				r.reserveRoute(rt)

				nextRemaining := state.remaining - size
				nextScore := state.score + logProb -
					float64(fees)/4_000_000 - 0.045

				nextRoutes := make(
					[]*route.Route, len(state.routes),
					len(state.routes)+1,
				)
				copy(nextRoutes, state.routes)
				nextRoutes = append(nextRoutes, rt)

				progress := float64(total-nextRemaining) /
					float64(total)
				expectedProgress := float64(len(nextRoutes)) /
					float64(parts)
				balancePenalty := 7.0 *
					math.Abs(progress-expectedProgress)

				next := candidatePlanState{
					remaining: nextRemaining,
					slots:     state.slots - 1,
					routes:    nextRoutes,
					reservations: candidateCopyReservations(
						r.reserved,
					),
					score: nextScore,
					rank:  nextScore - balancePenalty,
				}

				if nextRemaining == 0 {
					complete = append(complete, next)
					continue
				}
				if next.slots > 0 {
					expanded = append(expanded, next)
				}
			}
		}

		sort.Slice(expanded, func(i, j int) bool {
			if expanded[i].rank == expanded[j].rank {
				return expanded[i].remaining <
					expanded[j].remaining
			}
			return expanded[i].rank > expanded[j].rank
		})

		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		beam = expanded
	}

	if len(complete) == 0 {
		r.reserved = savedReservations
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	sort.Slice(complete, func(i, j int) bool {
		if complete[i].score == complete[j].score {
			return len(complete[i].routes) <
				len(complete[j].routes)
		}
		return complete[i].score > complete[j].score
	})

	return complete[0].routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		partAmt := candidateFinalAmount(rt)
		if partAmt > 0 && partAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else {
		belief.estimate =
			(belief.estimate*3 + estimate) / 4
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.suspect[key]++
		r.markRouteSuspect(rt, 1)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = 12 + int(maxParts)*2
	if r.attemptLimit < 14 {
		r.attemptLimit = 14
	}
	if r.attemptLimit > 48 {
		r.attemptLimit = 48
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		retryScale = 0.55 * math.Pow(1-ratio, 0.45)
		if retryScale < 0.10 {
			retryScale = 0.10
		}
		if failure.count > 1 {
			retryScale *= math.Pow(
				0.78, float64(failure.count-1),
			)
			if retryScale < 0.06 {
				retryScale = 0.06
			}
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.008 {
			p = 0.008
		}
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.99 - 0.975*pos
		p = 0.18*p + 0.82*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.35 {
			scale := 1 - 0.94*(ratio-0.35)/0.65
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.50 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	path     []*candidateEdge
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type candidateLabel struct {
	score    float64
	required lnwire.MilliSatoshi
}

func candidateAcceptLabel(labels map[route.Vertex][]candidateLabel,
	node route.Vertex, score float64,
	required lnwire.MilliSatoshi) bool {

	old := labels[node]
	for _, label := range old {
		if label.score <= score && label.required <= required {
			return false
		}
	}

	filtered := old[:0]
	for _, label := range old {
		if score <= label.score && required <= label.required {
			continue
		}
		filtered = append(filtered, label)
	}
	filtered = append(filtered, candidateLabel{
		score:    score,
		required: required,
	})

	if len(filtered) > 8 {
		sort.Slice(filtered, func(i, j int) bool {
			return filtered[i].score < filtered[j].score
		})
		filtered = filtered[:8]

		found := false
		for _, label := range filtered {
			if label.score == score &&
				label.required == required {

				found = true
				break
			}
		}
		if !found {
			labels[node] = filtered
			return false
		}
	}

	labels[node] = filtered
	return true
}

func candidateLabelLive(labels map[route.Vertex][]candidateLabel,
	item *candidateDijkstraItem) bool {

	for _, label := range labels[item.node] {
		if label.score == item.score &&
			label.required == item.required {

			return true
		}
	}
	return false
}

func candidatePathContains(path []*candidateEdge,
	node route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}
	return false
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 420_000.0
		hopPenalty = 1_200.0
		maxHops    = 20
	)

	labels := make(map[route.Vertex][]candidateLabel)
	labels[r.spec.Target] = []candidateLabel{{
		score:    0,
		required: amt,
	}}

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		if !candidateLabelLive(labels, item) {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(item.path, amt)
			if err != nil {
				return nil, 0, err
			}
			return rt, item.logProb, nil
		}

		if len(item.path) >= maxHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidatePathContains(item.path, edge.key.from) {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee
			if sending < amtOver {
				continue
			}

			utilization := float64(
				amtOver+r.reserved[edge.key],
			) / float64(edge.capacity)

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty +
				45_000*utilization*utilization

			edgeScore += float64(r.edgeUses[edge.key]) * 18_000
			edgeScore += float64(r.suspect[edge.key]) * 210_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 190_000
			}
			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}

			score := item.score + edgeScore
			if !candidateAcceptLabel(
				labels, edge.key.from, score, sending,
			) {
				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				path:     path,
			})
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}
	if path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("route endpoints do not match")
	}
	for i := 1; i < len(path); i++ {
		if path[i-1].key.to != path[i].key.from {
			return nil, fmt.Errorf("broken path at hop %d", i)
		}
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateCopyLogs(src map[candidateEdgeKey]float64) map[
	candidateEdgeKey]float64 {

	dst := make(map[candidateEdgeKey]float64, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func candidateReserve(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserve(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateRouteID(rt *route.Route) uint64 {
	h := uint64(1469598103934665603)
	for _, hop := range rt.Hops {
		h ^= candidateMix64(hop.ChannelID)
		h *= 1099511628211
	}
	return h
}

type candidateRouteChoice struct {
	rt *route.Route
}

func (r *candidateRouter) routeChoices(
	amt lnwire.MilliSatoshi) []candidateRouteChoice {

	first, _, err := r.findRoute(amt, nil)
	if err != nil {
		return nil
	}

	choices := []candidateRouteChoice{{rt: first}}
	seen := map[uint64]bool{candidateRouteID(first): true}

	penalty := make(map[candidateEdgeKey]float64)
	for i := range first.Hops {
		key, ok := candidateRouteEdgeKey(first, i)
		if ok {
			penalty[key] = 720_000
		}
	}

	alternate, _, err := r.findRoute(amt, penalty)
	if err == nil {
		id := candidateRouteID(alternate)
		if !seen[id] {
			choices = append(choices, candidateRouteChoice{
				rt: alternate,
			})
		}
	}

	return choices
}

func candidateAddPlanSize(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	remaining lnwire.MilliSatoshi, slots uint32) {

	if value <= 0 {
		value = 1
	}
	if value > remaining {
		value = remaining
	}
	if value != remaining {
		left := remaining - value
		if left < lnwire.MilliSatoshi(slots-1) {
			return
		}
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	avg := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	add := func(value lnwire.MilliSatoshi) {
		candidateAddPlanSize(
			&values, seen, value, remaining, slots,
		)
	}

	add(remaining)
	add(avg)
	add(avg * 3 / 4)
	add(avg * 5 / 4)
	add(avg * 3 / 2)
	add(avg * 2)
	add(remaining / 3)
	add(remaining / 2)
	add(remaining * 2 / 3)
	add(remaining * 3 / 4)

	if r.lastFailedShard > 0 {
		add(r.lastFailedShard / 2)
		add(r.lastFailedShard * 5 / 8)
		add(r.lastFailedShard * 3 / 4)
	}

	return values
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	edgeLogs     map[candidateEdgeKey]float64
	score        float64
	rank         float64
}

func (r *candidateRouter) extendPlan(state *candidatePlanState,
	rt *route.Route, total lnwire.MilliSatoshi) (
	*candidatePlanState, bool) {

	size := candidateFinalAmount(rt)
	if size <= 0 || size > state.remaining {
		return nil, false
	}

	reservations := candidateCopyReservations(state.reservations)
	logs := candidateCopyLogs(state.edgeLogs)
	saved := r.reserved
	r.reserved = reservations
	defer func() {
		r.reserved = saved
	}()

	increment := 0.0
	reused := 0

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return nil, false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return nil, false
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, false
		}

		p := r.probability(edge, amt)
		if p <= 0 {
			return nil, false
		}
		newLog := math.Log(p)

		if oldLog, ok := logs[key]; ok {
			delta := newLog - oldLog
			if delta > 0 {
				delta = 0
			}
			increment += delta
			if key.from != r.source {
				reused++
			}
		} else {
			increment += newLog
		}
		logs[key] = newLog
	}

	fees := rt.TotalAmount - size
	score := state.score + increment -
		float64(fees)/4_000_000 - 0.04 -
		float64(reused)*0.06

	candidateReserve(reservations, rt)
	routes := append([]*route.Route(nil), state.routes...)
	routes = append(routes, rt)
	remaining := state.remaining - size
	progress := 1 - float64(remaining)/float64(total)

	return &candidatePlanState{
		remaining:    remaining,
		routes:       routes,
		reservations: reservations,
		edgeLogs:     logs,
		score:        score,
		rank:         score + 1.35*progress,
	}, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		parts = 1
	}
	if parts > 16 {
		parts = 16
	}

	saved := r.reserved
	defer func() {
		r.reserved = saved
	}()

	states := []*candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(saved),
		edgeLogs:     make(map[candidateEdgeKey]float64),
	}}

	var best *candidatePlanState
	const beamWidth = 8

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		var next []*candidatePlanState

		for _, state := range states {
			if state.remaining == 0 {
				if best == nil || state.score > best.score {
					best = state
				}
				continue
			}

			sizes := r.planSizes(state.remaining, slots)
			for _, size := range sizes {
				r.reserved = state.reservations
				for _, choice := range r.routeChoices(size) {
					extended, ok := r.extendPlan(
						state, choice.rt, total,
					)
					if !ok {
						continue
					}
					if extended.remaining == 0 {
						if best == nil ||
							extended.score > best.score {

							best = extended
						}
						continue
					}
					if slots > 1 {
						next = append(next, extended)
					}
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return next[i].rank > next[j].rank
		})
		if len(next) > beamWidth {
			next = next[:beamWidth]
		}
		states = next
	}

	if best == nil || len(best.routes) == 0 {
		r.reserved = saved
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	return best.routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		partAmt := candidateFinalAmount(rt)
		if partAmt > 0 && partAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateFailure
	policyBlocked map[candidateEdgeKey]bool
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	routeFailures   map[uint64]uint32
	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		routeFailures:  make(map[uint64]uint32),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts) + 5
	if r.attemptLimit < 9 {
		r.attemptLimit = 9
	}
	if r.attemptLimit > 18 {
		r.attemptLimit = 18
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		if _, ok := r.edges[key]; ok {
			r.beliefs[key] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.050)
	highMode := 1 / (1 + math.Exp((x-0.92)/0.032))
	p := 0.46*lowMode + 0.54*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.986 {
		return 0.986
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9998
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case failure.count >= 3 && ratio > 0.26:
			return 0
		case failure.count >= 2 && ratio > 0.42:
			return 0
		case ratio > 0.68:
			return 0
		case ratio > 0.52:
			retryScale = 0.16
		case ratio > 0.36:
			retryScale = 0.38
		case ratio > 0.23:
			retryScale = 0.66
		default:
			retryScale = 0.88
		}
		if failure.count >= 2 {
			retryScale *= 0.72
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.002

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.996 - 0.993*pos
		p = 0.10*p + 0.90*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		switch {
		case ratio >= 0.82:
			p *= 0.04
		case ratio >= 0.60:
			p *= 0.15
		case ratio >= 0.40:
			p *= 0.38
		case ratio >= 0.24:
			p *= 0.68
		}

	case belief.lowerOK > 0:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		if distance > 0 {
			boost := 0.66 * math.Exp(-distance/0.17)
			p += boost * (1 - p)
		}
	}

	if belief.estimate > 0 {
		scale := 0.065 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.18
		evidence := belief.successes + belief.failures
		if evidence >= 2 {
			weight = 0.27
		}
		if evidence >= 5 {
			weight = 0.36
		}
		p = (1-weight)*p + weight*q
	}

	p *= retryScale
	if p < 0.0005 {
		return 0.0005
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	totalP := r.liquidityProbability(edge, reserved+amt)
	if totalP <= 0 {
		return 0
	}
	if reserved == 0 {
		return totalP
	}

	baseP := r.liquidityProbability(edge, reserved)
	if baseP <= 0 {
		return 0
	}

	p := totalP / baseP
	if p > 0.997 {
		return 0.997
	}
	if p < 0.0005 {
		return 0.0005
	}
	return p
}

type candidatePathLabel struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	edge     *candidateEdge
	next     *candidatePathLabel
	hops     int
	active   bool
	idx      int
}

type candidatePathQueue []*candidatePathLabel

func (q candidatePathQueue) Len() int {
	return len(q)
}

func (q candidatePathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidatePathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidatePathQueue) Push(x any) {
	item := x.(*candidatePathLabel)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidatePathQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidatePathContains(label *candidatePathLabel,
	node route.Vertex) bool {

	for cur := label; cur != nil; cur = cur.next {
		if cur.node == node {
			return true
		}
	}
	return false
}

func candidateInsertLabel(labels map[route.Vertex][]*candidatePathLabel,
	label *candidatePathLabel) bool {

	current := labels[label.node]
	for _, old := range current {
		if old.active && old.score <= label.score &&
			old.required <= label.required {

			return false
		}
	}

	kept := current[:0]
	for _, old := range current {
		if old.active && label.score <= old.score &&
			label.required <= old.required {

			old.active = false
			continue
		}
		if old.active {
			kept = append(kept, old)
		}
	}

	kept = append(kept, label)
	if len(kept) > 6 {
		sort.Slice(kept, func(i, j int) bool {
			li := kept[i].score +
				float64(kept[i].required)/16_000_000
			lj := kept[j].score +
				float64(kept[j].required)/16_000_000
			return li < lj
		})
		for _, old := range kept[6:] {
			old.active = false
		}
		kept = kept[:6]
	}

	labels[label.node] = kept
	return label.active
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 1_150_000.0
		hopPenalty = 70_000.0
		maxHops    = 24
		maxExpand  = 32000
	)

	target := &candidatePathLabel{
		node:     r.spec.Target,
		required: amt,
		active:   true,
	}
	labels := map[route.Vertex][]*candidatePathLabel{
		r.spec.Target: {target},
	}
	pq := &candidatePathQueue{}
	heap.Push(pq, target)

	expanded := 0
	var sourceLabel *candidatePathLabel

	for pq.Len() > 0 && expanded < maxExpand {
		item := heap.Pop(pq).(*candidatePathLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}
		if item.hops >= maxHops {
			continue
		}

		expanded++
		for _, edge := range r.incomingEdges[item.node] {
			if candidatePathContains(item, edge.key.from) {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			suspectPenalty := float64(r.suspect[edge.key]) * 650_000
			if failure := r.currentFails[edge.key]; failure.count > 1 {
				suspectPenalty += float64(failure.count-1) * 250_000
			}
			edgeScore += suspectPenalty

			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}

			label := &candidatePathLabel{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				edge:     edge,
				next:     item,
				hops:     item.hops + 1,
				active:   true,
			}
			if candidateInsertLabel(labels, label) {
				heap.Push(pq, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	for cur := sourceLabel; cur != nil && cur.edge != nil; cur = cur.next {
		path = append(path, cur.edge)
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLabel.logProb, nil
}

func (r *candidateRouter) findFreshRoute(amt lnwire.MilliSatoshi,
	basePenalty map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	rt, logProb, err := r.findRoute(amt, basePenalty)
	if err != nil {
		return nil, 0, err
	}

	failures := r.routeFailures[candidateRouteSignature(rt)]
	if failures == 0 {
		return rt, logProb, nil
	}

	penalty := make(map[candidateEdgeKey]float64)
	for key, value := range basePenalty {
		penalty[key] = value
	}
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		value := 900_000.0 * float64(failures)
		if key.from != r.source {
			value *= 1.5
		}
		penalty[key] += value
	}

	alternate, altProb, altErr := r.findRoute(amt, penalty)
	if altErr == nil &&
		candidateRouteSignature(alternate) != candidateRouteSignature(rt) {

		return alternate, altProb, nil
	}

	return rt, logProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	node := r.source
	for _, edge := range path {
		if edge.key.from != node {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, errors.New("path does not reach target")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))
	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, index int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return 0, false
	}
	if index == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[index-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}
	hop := rt.Hops[index]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteSignature(rt *route.Route) uint64 {
	var h uint64 = 1469598103934665603
	if rt == nil {
		return h
	}
	for i, hop := range rt.Hops {
		h ^= candidateMix64(
			hop.ChannelID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		h *= 1099511628211
	}
	return h
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) reliableLimit(edge *candidateEdge) (
	lnwire.MilliSatoshi, bool) {

	if edge == nil {
		return 0, false
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		return balance, ok
	}

	limit := edge.capacity * 9 / 10
	belief := r.beliefs[edge.key]

	if belief.lowerOK > limit {
		limit = belief.lowerOK
	}
	if belief.estimate > 0 && belief.failures > 0 &&
		belief.estimate < limit {

		limit = belief.estimate
	}
	if belief.upperFail > 0 {
		upper := belief.upperFail * 13 / 20
		if upper < limit {
			limit = upper
		}
	}
	if failure := r.currentFails[edge.key]; failure.upper > 0 {
		upper := failure.upper * 11 / 20
		if failure.count >= 2 {
			upper = failure.upper * 7 / 20
		}
		if upper < limit {
			limit = upper
		}
	}

	return limit, true
}

func (r *candidateRouter) routeHeadroom(rt *route.Route) (
	lnwire.MilliSatoshi, bool) {

	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 {
		return 0, false
	}

	ratio := math.Inf(1)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0, false
		}
		edge := r.edges[key]
		limit, ok := r.reliableLimit(edge)
		if !ok {
			return 0, false
		}

		used := r.reserved[key]
		if limit <= used {
			return 0, false
		}
		available := limit - used

		amt, ok := candidateRouteAmount(rt, i)
		if !ok || amt <= 0 {
			return 0, false
		}

		edgeRatio := float64(available) / float64(amt)
		if edge.maxHTLC > 0 {
			maxRatio := float64(edge.maxHTLC) / float64(amt)
			if maxRatio < edgeRatio {
				edgeRatio = maxRatio
			}
		}
		if edgeRatio < ratio {
			ratio = edgeRatio
		}
	}

	if math.IsInf(ratio, 1) || ratio <= 0 {
		return 0, false
	}

	headroom := lnwire.MilliSatoshi(float64(finalAmt) * ratio)
	if headroom <= 0 {
		return 0, false
	}
	return headroom, true
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	avg := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	for _, value := range []lnwire.MilliSatoshi{
		avg / 2,
		avg * 2 / 3,
		avg * 4 / 5,
		avg,
		avg * 6 / 5,
		avg * 3 / 2,
		avg * 2,
	} {
		candidateAddAmount(
			&sizes, seen, value, minimum, maximum,
		)
	}

	if r.lastFailedShard > 0 {
		for _, value := range []lnwire.MilliSatoshi{
			r.lastFailedShard / 4,
			r.lastFailedShard * 7 / 20,
			r.lastFailedShard / 2,
			r.lastFailedShard * 3 / 5,
		} {
			candidateAddAmount(
				&sizes, seen, value, minimum, maximum,
			)
		}
	}

	probe, _, err := r.findFreshRoute(avg, nil)
	if err == nil {
		if headroom, ok := r.routeHeadroom(probe); ok {
			for _, value := range []lnwire.MilliSatoshi{
				headroom * 3 / 5,
				headroom * 3 / 4,
				headroom * 7 / 8,
				headroom,
			} {
				candidateAddAmount(
					&sizes, seen, value, minimum, maximum,
				)
			}
		}
	}

	sort.Slice(sizes, func(i, j int) bool {
		di := math.Abs(math.Log(
			float64(sizes[i]) / float64(avg),
		))
		dj := math.Abs(math.Log(
			float64(sizes[j]) / float64(avg),
		))
		if di == dj {
			return sizes[i] > sizes[j]
		}
		return di < dj
	})
	if len(sizes) > 11 {
		sizes = sizes[:11]
	}

	return sizes
}

func candidateDiversityPenalty(rt *route.Route) map[candidateEdgeKey]float64 {
	penalty := make(map[candidateEdgeKey]float64)
	if rt == nil {
		return penalty
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == rt.SourcePubKey {
			penalty[key] += 300_000
		} else {
			penalty[key] += 1_600_000
		}
	}
	return penalty
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations, base map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	score := 0.0
	for key, amount := range reservations {
		oldAmount := base[key]
		if amount <= oldAmount {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, amount)
		if p <= 0 {
			return math.Inf(-1)
		}
		if oldAmount > 0 {
			oldP := r.liquidityProbability(edge, oldAmount)
			if oldP <= 0 {
				return math.Inf(-1)
			}
			p /= oldP
		}
		if p > 0.999 {
			p = 0.999
		}
		if p < 0.0005 {
			p = 0.0005
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)
	for _, rt := range routes {
		finalAmt := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmt {
			fees += rt.TotalAmount - finalAmt
		}
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 35_000_000
	if len(routes) > 1 {
		score -= 0.012 * float64(len(routes)-1)
	}
	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.035 * float64(count-1)
		}
	}

	return score
}

func (r *candidateRouter) completionRank(state *candidatePlanState) float64 {
	if state.remaining == 0 {
		return state.score
	}
	if state.slots <= 0 {
		return math.Inf(-1)
	}

	saved := r.reserved
	r.reserved = candidateCopyReservations(state.reservations)
	defer func() {
		r.reserved = saved
	}()

	avg := (state.remaining + lnwire.MilliSatoshi(state.slots) - 1) /
		lnwire.MilliSatoshi(state.slots)

	_, logProb, err := r.findFreshRoute(avg, nil)
	if err != nil {
		return math.Inf(-1)
	}

	future := 0.72 * float64(state.slots) * logProb
	return state.score + future
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 10

	base := candidateCopyReservations(r.reserved)
	saved := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = saved
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(base),
	}}

	for depth := 0; depth < parts; depth++ {
		var expanded []candidatePlanState

		for _, state := range states {
			r.reserved = candidateCopyReservations(
				state.reservations,
			)
			sizes := r.shardSizes(state.remaining, state.slots)

			for _, size := range sizes {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				first, _, err := r.findFreshRoute(size, nil)
				if err != nil {
					continue
				}

				options := []*route.Route{first}
				alternate, _, altErr := r.findFreshRoute(
					size, candidateDiversityPenalty(first),
				)
				if altErr == nil &&
					candidateRouteSignature(alternate) !=
						candidateRouteSignature(first) {

					options = append(options, alternate)
				}

				for _, rt := range options {
					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserveInto(reservations, rt)

					routes := append(
						append(
							[]*route.Route(nil),
							state.routes...,
						),
						rt,
					)
					remaining := state.remaining - size
					slots := state.slots - 1
					if (remaining == 0) != (slots == 0) {
						continue
					}

					next := candidatePlanState{
						remaining:    remaining,
						slots:        slots,
						routes:       routes,
						reservations: reservations,
					}
					next.score = r.planScore(
						routes, reservations, base,
					)
					if math.IsInf(next.score, -1) {
						continue
					}
					next.rank = r.completionRank(&next)
					if math.IsInf(next.rank, -1) {
						continue
					}
					expanded = append(expanded, next)
				}
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.Slice(expanded, func(i, j int) bool {
			if expanded[i].rank == expanded[j].rank {
				return expanded[i].score > expanded[j].score
			}
			return expanded[i].rank > expanded[j].rank
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	var best *candidatePlanState
	for i := range states {
		state := &states[i]
		if state.remaining != 0 || state.slots != 0 {
			continue
		}
		if best == nil || state.score > best.score {
			best = state
		}
	}
	if best == nil {
		return nil, 0, false
	}
	return best.routes, best.score, true
}

func candidatePartCounts(maxParts int) []int {
	seen := make(map[int]bool)
	var counts []int

	add := func(value int) {
		if value >= 2 && value <= maxParts && !seen[value] {
			seen[value] = true
			counts = append(counts, value)
		}
	}

	if maxParts <= 7 {
		for i := 2; i <= maxParts; i++ {
			add(i)
		}
	} else {
		for _, value := range []int{
			2, 3, 4, 5, 6, 8, 12, maxParts,
		} {
			add(value)
		}
	}

	sort.Ints(counts)
	return counts
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	full, fullLogProb, fullErr := r.findFreshRoute(total, nil)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	if fullErr == nil && fullLogProb >= math.Log(0.94) &&
		r.lastFailedShard == 0 {

		return []*route.Route{full}, nil
	}

	base := candidateCopyReservations(r.reserved)
	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(base)
		candidateReserveInto(reservations, full)
		bestPlan = []*route.Route{full}
		bestScore = r.planScore(bestPlan, reservations, base)
	}

	for _, count := range candidatePartCounts(int(parts)) {
		plan, score, ok := r.planWithParts(total, count)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}
	return bestPlan, nil
}

func (r *candidateRouter) routeFits(rt *route.Route) bool {
	if rt == nil || len(rt.Hops) == 0 {
		return false
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil {
			return false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok || r.probability(edge, amt) <= 0 {
			return false
		}
	}
	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt && r.routeFits(rt) {
			r.planned = r.planned[1:]
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil && edge.capacity > 0 {
		ratio := float64(amt) / float64(edge.capacity)
		switch {
		case ratio >= 0.07:
			estimate = edge.capacity * 9 / 10
		case ratio >= 0.025:
			estimate = edge.capacity * 4 / 5
		default:
			estimate = amt * 3
		}
		if estimate > edge.capacity {
			estimate = edge.capacity
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt / 4
	if edge := r.edges[key]; edge != nil {
		lowEstimate := edge.capacity / 20
		if estimate > lowEstimate {
			estimate = lowEstimate
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	if rt == nil {
		return
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	signature := candidateRouteSignature(rt)

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
			if r.suspect[key] > 0 {
				r.suspect[key]--
			}
		}

		delete(r.routeFailures, signature)
		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.routeFailures[signature]++

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 3)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 6
		r.lastFailedShard = candidateFinalAmount(rt)

	default:
		r.suspect[key] += 4
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeHeat      map[candidateEdgeKey]uint32
	routeFailures map[uint64]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))

	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeHeat:       make(map[candidateEdgeKey]uint32),
		routeFailures:  make(map[uint64]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = 12 + 3*int(maxParts)
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 42 {
		r.attemptLimit = 42
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if amt <= 0 || capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.043)
	highMode := 1 / (1 + math.Exp((x-0.915)/0.034))
	p := 0.46*lowMode + 0.54*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.988 {
		return 0.988
	}

	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity || r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.80:
			retryScale = 0.015
		case ratio > 0.66:
			retryScale = 0.07
		case ratio > 0.52:
			retryScale = 0.20
		case ratio > 0.38:
			retryScale = 0.42
		case ratio > 0.25:
			retryScale = 0.66
		default:
			retryScale = 0.86
		}
		if failure.count >= 2 {
			retryScale *= 0.65
		}
		if failure.count >= 4 {
			retryScale *= 0.50
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.004

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		evidence := 0.995 - 0.991*position
		p = 0.08*p + 0.92*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.20 {
			scale := 1 - 0.95*(ratio-0.20)/0.80
			if scale < 0.04 {
				scale = 0.04
			}
			p *= scale
		}

	case belief.lowerOK > 0:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		if distance > 0 {
			boost := 0.72 * math.Exp(-distance/0.18)
			p += boost * (1 - p)
		}
	}

	if belief.estimate > 0 {
		scale := 0.065 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateProbability := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.22
		if belief.successes+belief.failures >= 3 {
			weight = 0.34
		}
		p = (1-weight)*p + weight*estimateProbability
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}

	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	return r.liquidityProbability(edge, reserved+amt)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 245_000.0
		hopPenalty = 900.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProbability float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProbability = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOverEdge := item.required
			probability := r.probability(edge, amountOverEdge)
			if probability <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			sending := amountOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(probability)) +
				hopPenalty

			heat := r.edgeHeat[edge.key]
			edgeScore += float64(heat) * 85_000
			edgeScore += extraPenalty[edge.key]

			if r.reserved[edge.key] > 0 &&
				edge.key.from != r.source {

				edgeScore += 65_000
			}

			score := item.score + edgeScore
			oldScore, found := bestScore[edge.key.from]
			if found && score >= oldScore {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(probability),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] + outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route,
	channelIndex int) (lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}

	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}

	hop := rt.Hops[channelIndex]
	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(
			key.chanID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		h ^= candidateMix64(candidateVertexHash(key.to))
	}

	return candidateMix64(h)
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		result[key] = amount
	}

	return result
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}

	for _, rt := range r.held[len(r.held)-count:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	equal := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&values, seen, equal, minimum, maximum)
	candidateAddAmount(&values, seen, equal*2/3, minimum, maximum)
	candidateAddAmount(&values, seen, equal*4/5, minimum, maximum)
	candidateAddAmount(&values, seen, equal*6/5, minimum, maximum)
	candidateAddAmount(&values, seen, equal*3/2, minimum, maximum)
	candidateAddAmount(&values, seen, equal*2, minimum, maximum)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard/4, minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/3, minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*2/5,
			minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/2, minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*3/5,
			minimum, maximum,
		)
	}

	for _, edge := range r.edges {
		if edge.key.from != r.source &&
			edge.key.to != r.spec.Target {

			continue
		}

		available := edge.capacity - r.reserved[edge.key]
		if available <= 0 {
			continue
		}

		candidateAddAmount(
			&values, seen, available*2/5, minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, available*3/5, minimum, maximum,
		)
		candidateAddAmount(
			&values, seen, available*4/5, minimum, maximum,
		)

		belief, ok := r.beliefs[edge.key]
		if !ok {
			continue
		}

		if belief.lowerOK > r.reserved[edge.key] {
			candidateAddAmount(
				&values, seen,
				belief.lowerOK-r.reserved[edge.key],
				minimum, maximum,
			)
		}
		if belief.upperFail > r.reserved[edge.key] {
			room := belief.upperFail - r.reserved[edge.key]
			candidateAddAmount(
				&values, seen, room*2/5, minimum, maximum,
			)
			candidateAddAmount(
				&values, seen, room*3/5, minimum, maximum,
			)
		}
	}

	sort.SliceStable(values, func(i, j int) bool {
		di := math.Abs(float64(values[i] - equal))
		dj := math.Abs(float64(values[j] - equal))
		return di < dj
	})

	const maximumCandidates = 12
	if len(values) > maximumCandidates {
		values = values[:maximumCandidates]
	}

	return values
}

type candidateRouteOption struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeOptions(
	amt lnwire.MilliSatoshi) []candidateRouteOption {

	const searches = 6

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	var options []candidateRouteOption
	var rejected *candidateRouteOption

	for search := 0; search < searches; search++ {
		rt, logProbability, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			option := candidateRouteOption{
				route:   rt,
				logProb: logProbability,
			}

			if r.routeFailures[hash] == 0 {
				options = append(options, option)
			} else if rejected == nil {
				copy := option
				rejected = &copy
			}
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}

			penalty := 520_000.0
			if key.from == r.source {
				penalty = 210_000
			}
			penalties[key] += penalty
		}

		if len(options) >= 4 {
			break
		}
	}

	if len(options) == 0 && rejected != nil {
		options = append(options, *rejected)
	}

	return options
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	base, reservations map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	score := 0.0
	for key, amount := range reservations {
		if amount <= base[key] {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		probability := r.liquidityProbability(edge, amount)
		if probability <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(probability)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)

	for _, rt := range routes {
		finalAmount := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmount {
			fees += rt.TotalAmount - finalAmount
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 4_000_000
	score -= 0.025 * float64(len(routes)-1)

	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.11 * float64(count-1)
		}
		score -= 0.06 * float64(r.edgeHeat[key])
	}

	return score
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 9

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	base := candidateCopyReservations(r.reserved)
	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(base),
	}}

	for depth := 0; depth < parts; depth++ {
		var expanded []candidatePlanState

		for _, state := range states {
			sizes := r.shardSizes(state.remaining, state.slots)
			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				options := r.routeOptions(size)

				for _, option := range options {
					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserveInto(
						reservations, option.route,
					)

					remaining := state.remaining - size
					slots := state.slots - 1
					if (remaining == 0) != (slots == 0) {
						continue
					}

					routes := append(
						append(
							[]*route.Route(nil),
							state.routes...,
						),
						option.route,
					)

					nextState := candidatePlanState{
						remaining:    remaining,
						slots:        slots,
						routes:       routes,
						reservations: reservations,
					}
					nextState.score = r.planScore(
						routes, base, reservations,
					)
					if math.IsInf(nextState.score, -1) {
						continue
					}

					expanded = append(expanded, nextState)
				}
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.SliceStable(expanded, func(i, j int) bool {
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	for _, state := range states {
		if state.remaining == 0 && state.slots == 0 {
			return state.routes, state.score, true
		}
	}

	return nil, 0, false
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	parts int) (*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total, nil)
		return rt, err
	}

	var best *route.Route
	bestUtility := math.Inf(-1)

	for slots := parts; slots >= 2; slots-- {
		for _, size := range r.shardSizes(total, slots) {
			options := r.routeOptions(size)
			for _, option := range options {
				progress := float64(size) / float64(total)
				utility := option.logProb + 0.55*progress

				fee := option.route.TotalAmount -
					candidateFinalAmount(option.route)
				utility -= float64(fee) / 4_000_000

				if utility > bestUtility {
					bestUtility = utility
					best = option.route
				}
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}

	return best, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	full, fullLogProbability, fullErr := r.findRoute(total, nil)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	if fullErr == nil &&
		fullLogProbability >= math.Log(0.965) &&
		r.lastFailedShard == 0 {

		return []*route.Route{full}, nil
	}

	maxPlanParts := int(parts)
	if maxPlanParts > 14 {
		maxPlanParts = 14
	}
	if lnwire.MilliSatoshi(maxPlanParts) > total {
		maxPlanParts = int(total)
	}
	if maxPlanParts < 1 {
		return nil, errors.New("payment amount too small")
	}

	base := candidateCopyReservations(r.reserved)
	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(base)
		candidateReserveInto(reservations, full)
		bestPlan = []*route.Route{full}
		bestScore = r.planScore(bestPlan, base, reservations)
	}

	for count := 2; count <= maxPlanParts; count++ {
		plan, score, ok := r.planWithParts(total, count)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan != nil {
		return bestPlan, nil
	}

	shard, err := r.fallbackShard(total, int(parts))
	if err != nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	return []*route.Route{shard}, nil
}

func (r *candidateRouter) routeFits(rt *route.Route) bool {
	added := make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}

		edge := r.edges[key]
		if edge == nil || r.policyBlocked[key] {
			return false
		}

		amount, ok := candidateRouteAmount(rt, i)
		if !ok || !edge.policyAllows(amount) {
			return false
		}

		added[key] += amount
		total := r.reserved[key] + added[key]
		if total > edge.capacity {
			return false
		}

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok || total > balance {
				return false
			}
		}

		if failure, ok := r.currentFails[key]; ok &&
			failure.upper > 0 && total >= failure.upper {

			return false
		}
	}

	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt && r.routeFits(rt) {
			r.planned = r.planned[1:]
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amount >= failure.upper {

		delete(r.currentFails, key)
	}

	if heat := r.edgeHeat[key]; heat > 0 {
		r.edgeHeat[key] = heat - 1
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amount > belief.lowerOK {
		belief.lowerOK = amount
	}
	if belief.upperFail > 0 && amount >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amount
	if edge := r.edges[key]; edge != nil {
		highEstimate := edge.capacity * 17 / 20
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amount < current.upper {
		current.upper = amount
	}
	current.count++
	r.currentFails[key] = current
	r.edgeHeat[key] += 2

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amount < belief.upperFail {
		belief.upperFail = amount
	}
	if belief.lowerOK >= amount {
		belief.lowerOK = 0
	}

	estimate := amount / 4
	if edge := r.edges[key]; edge != nil {
		floor := edge.capacity / 20
		if estimate > floor {
			estimate = floor
		}
	}
	if estimate <= 0 {
		estimate = 1
	}

	if belief.estimate == 0 || belief.estimate >= amount ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteUncertain(rt *route.Route,
	weight uint32) {

	hash := candidateRouteHash(rt)
	r.routeFailures[hash] += weight

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.edgeHeat[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amount+r.reserved[key])
		}

		delete(r.routeFailures, candidateRouteHash(rt))
		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteUncertain(rt, 2)
		return nil
	}

	passedEdges := failureIndex
	if passedEdges > len(rt.Hops) {
		passedEdges = len(rt.Hops)
	}

	for i := 0; i < passedEdges; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markRouteUncertain(rt, 2)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteUncertain(rt, 2)
		return nil
	}

	amountOverEdge, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteUncertain(rt, 2)
		return nil
	}
	totalRequired := amountOverEdge + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.edgeHeat[key] += 4

	default:
		r.markRouteUncertain(rt, 2)
		r.edgeHeat[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts) + 4
	if r.attemptLimit < 8 {
		r.attemptLimit = 8
	}
	if r.attemptLimit > 18 {
		r.attemptLimit = 18
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if amt <= 0 || capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.034))
	p := 0.47*lowMode + 0.53*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity || r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case failure.count >= 3 && ratio > 0.34:
			return 0
		case failure.count >= 2 && ratio > 0.52:
			return 0
		case ratio > 0.78:
			return 0
		case ratio > 0.62:
			retryScale = 0.22
		case ratio > 0.46:
			retryScale = 0.46
		case ratio > 0.30:
			retryScale = 0.68
		default:
			retryScale = 0.86
		}
		if failure.count >= 2 {
			retryScale *= 0.72
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.004

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.994 - 0.988*pos
		p = 0.12*p + 0.88*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.20 {
			scale := 1 - 0.91*(ratio-0.20)/0.80
			if scale < 0.09 {
				scale = 0.09
			}
			p *= scale
		}

	case belief.lowerOK > 0:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.62 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.07 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.16
		count := belief.successes + belief.failures
		if count >= 2 {
			weight = 0.24
		}
		if count >= 4 {
			weight = 0.31
		}
		p = (1-weight)*p + weight*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	totalP := r.liquidityProbability(edge, reserved+amt)
	if totalP <= 0 {
		return 0
	}
	if reserved == 0 {
		return totalP
	}

	baseP := r.liquidityProbability(edge, reserved)
	if baseP <= 0 {
		return 0
	}

	p := totalP / baseP
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

type candidatePathLabel struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	edge     *candidateEdge
	next     *candidatePathLabel
	hops     int
	active   bool
	idx      int
}

type candidatePathQueue []*candidatePathLabel

func (q candidatePathQueue) Len() int {
	return len(q)
}

func (q candidatePathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidatePathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidatePathQueue) Push(x any) {
	item := x.(*candidatePathLabel)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidatePathQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidatePathContains(label *candidatePathLabel,
	node route.Vertex) bool {

	for cur := label; cur != nil; cur = cur.next {
		if cur.node == node {
			return true
		}
	}
	return false
}

func candidateInsertLabel(labels map[route.Vertex][]*candidatePathLabel,
	label *candidatePathLabel) bool {

	current := labels[label.node]
	for _, old := range current {
		if old.active && old.score <= label.score &&
			old.required <= label.required {

			return false
		}
	}

	kept := current[:0]
	for _, old := range current {
		if old.active && label.score <= old.score &&
			label.required <= old.required {

			old.active = false
			continue
		}
		if old.active {
			kept = append(kept, old)
		}
	}

	kept = append(kept, label)
	if len(kept) > 7 {
		sort.Slice(kept, func(i, j int) bool {
			li := kept[i].score +
				float64(kept[i].required)/12_000_000
			lj := kept[j].score +
				float64(kept[j].required)/12_000_000
			return li < lj
		})
		for _, old := range kept[7:] {
			old.active = false
		}
		kept = kept[:7]
	}

	labels[label.node] = kept
	return label.active
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 360_000.0
		hopPenalty = 18_000.0
		maxHops    = 32
		maxExpand  = 50000
	)

	target := &candidatePathLabel{
		node:     r.spec.Target,
		required: amt,
		active:   true,
	}
	labels := map[route.Vertex][]*candidatePathLabel{
		r.spec.Target: {target},
	}
	pq := &candidatePathQueue{}
	heap.Push(pq, target)

	expanded := 0
	var sourceLabel *candidatePathLabel

	for pq.Len() > 0 && expanded < maxExpand {
		item := heap.Pop(pq).(*candidatePathLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}
		if item.hops >= maxHops {
			continue
		}

		expanded++
		for _, edge := range r.incomingEdges[item.node] {
			if candidatePathContains(item, edge.key.from) {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.suspect[edge.key]) * 180_000
			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}

			label := &candidatePathLabel{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				edge:     edge,
				next:     item,
				hops:     item.hops + 1,
				active:   true,
			}
			if candidateInsertLabel(labels, label) {
				heap.Push(pq, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	for cur := sourceLabel; cur != nil && cur.edge != nil; cur = cur.next {
		path = append(path, cur.edge)
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLabel.logProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	node := r.source
	for _, edge := range path {
		if edge.key.from != node {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, errors.New("path does not reach target")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))
	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}
	seen[value] = true
	*values = append(*values, value)
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations, base map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	score := 0.0
	for key, amount := range reservations {
		oldAmount := base[key]
		if amount <= oldAmount {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, amount)
		if p <= 0 {
			return math.Inf(-1)
		}
		if oldAmount > 0 {
			oldP := r.liquidityProbability(edge, oldAmount)
			if oldP <= 0 {
				return math.Inf(-1)
			}
			p /= oldP
		}
		if p < 0.001 {
			p = 0.001
		}
		if p > 0.999 {
			p = 0.999
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)
	for _, rt := range routes {
		finalAmt := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmt {
			fees += rt.TotalAmount - finalAmt
		}
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 10_000_000
	if len(routes) > 1 {
		score -= 0.09 * float64(len(routes)-1)
	}
	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.035 * float64(count-1)
		}
	}

	return score
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	avg := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	for _, value := range []lnwire.MilliSatoshi{
		avg / 2,
		avg * 2 / 3,
		avg * 4 / 5,
		avg,
		avg * 6 / 5,
		avg * 3 / 2,
		avg * 2,
		maximum,
	} {
		candidateAddAmount(
			&sizes, seen, value, minimum, maximum,
		)
	}

	if r.lastFailedShard > 0 {
		for _, value := range []lnwire.MilliSatoshi{
			r.lastFailedShard * 3 / 10,
			r.lastFailedShard * 2 / 5,
			r.lastFailedShard / 2,
			r.lastFailedShard * 3 / 5,
		} {
			candidateAddAmount(
				&sizes, seen, value, minimum, maximum,
			)
		}
	}

	for key, edge := range r.edges {
		reserved := r.reserved[key]
		belief := r.beliefs[key]

		if belief.lowerOK > reserved {
			candidateAddAmount(
				&sizes, seen,
				(belief.lowerOK-reserved)*19/20,
				minimum, maximum,
			)
		}
		if belief.upperFail > reserved {
			available := belief.upperFail - reserved
			candidateAddAmount(
				&sizes, seen, available*2/5,
				minimum, maximum,
			)
			candidateAddAmount(
				&sizes, seen, available*11/20,
				minimum, maximum,
			)
		}
		if belief.estimate > reserved {
			candidateAddAmount(
				&sizes, seen,
				(belief.estimate-reserved)*4/5,
				minimum, maximum,
			)
		}

		available := edge.capacity - reserved
		if edge.key.from == r.source {
			if balance, ok := r.localBalances[edge.key.chanID]; ok {
				available = balance - reserved
			}
		}
		if available > 0 {
			candidateAddAmount(
				&sizes, seen, available*4/5,
				minimum, maximum,
			)
		}
	}

	sort.Slice(sizes, func(i, j int) bool {
		di := math.Abs(math.Log(
			float64(sizes[i]) / float64(avg),
		))
		dj := math.Abs(math.Log(
			float64(sizes[j]) / float64(avg),
		))
		if di == dj {
			return sizes[i] > sizes[j]
		}
		return di < dj
	})
	if len(sizes) > 14 {
		sizes = sizes[:14]
	}

	return sizes
}

func candidateRouteSignature(rt *route.Route) uint64 {
	var h uint64 = 1469598103934665603
	for i, hop := range rt.Hops {
		h ^= candidateMix64(
			hop.ChannelID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		h *= 1099511628211
	}
	return h
}

func candidateDiversityPenalty(rt *route.Route) map[candidateEdgeKey]float64 {
	penalty := make(map[candidateEdgeKey]float64)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == rt.SourcePubKey {
			penalty[key] += 130_000
		} else {
			penalty[key] += 620_000
		}
	}
	return penalty
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 10

	base := candidateCopyReservations(r.reserved)
	saved := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = saved
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(base),
	}}

	for depth := 0; depth < parts; depth++ {
		var expanded []candidatePlanState

		for _, state := range states {
			r.reserved = candidateCopyReservations(
				state.reservations,
			)
			sizes := r.shardSizes(state.remaining, state.slots)
			ideal := float64(state.remaining) / float64(state.slots)

			for _, size := range sizes {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				first, _, err := r.findRoute(size, nil)
				if err != nil {
					continue
				}

				options := []*route.Route{first}
				if depth < 3 {
					alternate, _, altErr := r.findRoute(
						size, candidateDiversityPenalty(first),
					)
					if altErr == nil &&
						candidateRouteSignature(alternate) !=
							candidateRouteSignature(first) {

						options = append(options, alternate)
					}
				}

				for _, rt := range options {
					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserveInto(reservations, rt)

					routes := append(
						append([]*route.Route(nil), state.routes...),
						rt,
					)
					remaining := state.remaining - size
					slots := state.slots - 1
					if (remaining == 0) != (slots == 0) {
						continue
					}

					next := candidatePlanState{
						remaining:    remaining,
						slots:        slots,
						routes:       routes,
						reservations: reservations,
					}
					next.score = r.planScore(
						routes, reservations, base,
					)

					if slots > 0 {
						ratio := float64(size) / ideal
						if ratio > 0 {
							next.score -= 0.06 *
								math.Abs(math.Log(ratio))
						}
					}
					if math.IsInf(next.score, -1) {
						continue
					}
					expanded = append(expanded, next)
				}
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.Slice(expanded, func(i, j int) bool {
			if expanded[i].score == expanded[j].score {
				return len(expanded[i].routes) <
					len(expanded[j].routes)
			}
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	for _, state := range states {
		if state.remaining == 0 && state.slots == 0 {
			return state.routes, state.score, true
		}
	}
	return nil, 0, false
}

func candidatePartCounts(maxParts int) []int {
	seen := make(map[int]bool)
	var counts []int
	add := func(v int) {
		if v >= 2 && v <= maxParts && !seen[v] {
			seen[v] = true
			counts = append(counts, v)
		}
	}

	if maxParts <= 8 {
		for i := 2; i <= maxParts; i++ {
			add(i)
		}
	} else {
		for _, value := range []int{
			2, 3, 4, 5, 6, 8, 10, 12, 16, maxParts,
		} {
			add(value)
		}
	}
	sort.Ints(counts)
	return counts
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	divisor := lnwire.MilliSatoshi(parts)
	ideal := (total + divisor - 1) / divisor
	seen := make(map[lnwire.MilliSatoshi]bool)
	var sizes []lnwire.MilliSatoshi

	add := func(size lnwire.MilliSatoshi) {
		if size <= 0 || size > total || seen[size] {
			return
		}
		seen[size] = true
		sizes = append(sizes, size)
	}

	add(ideal * 3 / 2)
	add(ideal)
	add(ideal * 4 / 5)
	add(ideal * 2 / 3)
	add(ideal / 2)
	add(total / 2)
	add(total / 3)
	add(total / 4)
	add(total / 6)
	add(total / 8)

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] > sizes[j]
	})

	for _, size := range sizes {
		rt, _, err := r.findRoute(size, nil)
		if err == nil {
			return rt, nil
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	full, fullLogProb, fullErr := r.findRoute(total, nil)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	if fullErr == nil && fullLogProb >= math.Log(0.97) &&
		r.lastFailedShard == 0 {

		return []*route.Route{full}, nil
	}

	base := candidateCopyReservations(r.reserved)
	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(base)
		candidateReserveInto(reservations, full)
		bestPlan = []*route.Route{full}
		bestScore = r.planScore(bestPlan, reservations, base)
	}

	for _, count := range candidatePartCounts(int(parts)) {
		plan, score, ok := r.planWithParts(total, count)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan != nil {
		return bestPlan, nil
	}

	fallback, err := r.fallbackShard(total, parts)
	if err != nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return nil, err
	}
	return []*route.Route{fallback}, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil && edge.capacity > 0 {
		ratio := float64(amt) / float64(edge.capacity)
		switch {
		case ratio >= 0.08:
			estimate = edge.capacity * 7 / 8
		case ratio >= 0.035:
			estimate = edge.capacity * 3 / 4
		default:
			estimate = amt * 2
		}
		if estimate > edge.capacity {
			estimate = edge.capacity
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt / 3
	if edge := r.edges[key]; edge != nil {
		lowEstimate := edge.capacity / 18
		if estimate > lowEstimate {
			estimate = lowEstimate
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
			if r.suspect[key] > 0 {
				r.suspect[key]--
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 4
		r.lastFailedShard = candidateFinalAmount(rt)

	default:
		r.suspect[key] += 3
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateAttemptKey struct {
	routeHash uint64
	amount    lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32
	tried         map[candidateAttemptKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	shardCeiling    lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		tried:          make(map[candidateAttemptKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 24
	if r.attemptLimit < 36 {
		r.attemptLimit = 36
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.047)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.031))
	p := 0.47*lowMode + 0.53*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.988 {
		return 0.988
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case failure.count >= 3 && ratio > 0.30:
			return 0
		case failure.count >= 2 && ratio > 0.48:
			return 0
		case ratio > 0.72:
			return 0
		case ratio > 0.56:
			retryScale = 0.12
		case ratio > 0.40:
			retryScale = 0.31
		case ratio > 0.25:
			retryScale = 0.55
		default:
			retryScale = 0.78
		}
		if failure.count >= 2 {
			retryScale *= 0.60
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.004

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		evidence := 0.994 - 0.988*position
		p = 0.10*p + 0.90*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.25 {
			scale := 1 - 0.95*(ratio-0.25)/0.75
			if scale < 0.045 {
				scale = 0.045
			}
			p *= scale
		}

	case belief.lowerOK > 0 && total > belief.lowerOK:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.68 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.075 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.28
		if belief.successes+belief.failures >= 3 {
			weight = 0.40
		}
		p = (1-weight)*p + weight*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	return r.liquidityProbability(edge, reserved+amt)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 390_000.0
		hopPenalty = 4_000.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOverEdge := item.required
			p := r.probability(edge, amountOverEdge)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			sending := amountOverEdge + fee

			score := item.score + float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			uses := r.edgeUses[edge.key]
			if uses > 8 {
				uses = 8
			}
			score += float64(uses) * 15_000

			suspect := r.suspect[edge.key]
			if suspect > 5 {
				suspect = 5
			}
			score += float64(suspect) * 115_000

			if extraPenalty != nil {
				score += extraPenalty[edge.key]
			}

			if r.reserved[edge.key] > 0 &&
				edge.key.from != r.source {

				score += 95_000
			}

			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i, hop := range rt.Hops {
		x := candidateMix64(hop.ChannelID + uint64(i+1))
		x ^= candidateMix64(candidateVertexHash(hop.PubKeyBytes))
		h = candidateMix64(h ^ x)
	}
	return h
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	copyMap := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		copyMap[key] = amount
	}
	return copyMap
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) topRoutes(amt lnwire.MilliSatoshi,
	limit int) []candidateRouteChoice {

	if limit < 1 {
		limit = 1
	}

	penalty := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	var choices []candidateRouteChoice

	for iteration := 0; iteration < limit*5; iteration++ {
		rt, logProb, err := r.findRoute(amt, penalty)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				logProb: logProb,
			})
			if len(choices) >= limit {
				break
			}
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			if key.from == r.source {
				penalty[key] += 90_000
			} else {
				penalty[key] += 310_000
			}
		}
	}

	return choices
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) evidenceHints(minimum,
	maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if maximum < minimum {
		return nil
	}

	var hints []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	for _, edge := range r.incomingEdges[r.spec.Target] {
		candidateAddAmount(
			&hints, seen, edge.capacity*7/8, minimum, maximum,
		)

		belief := r.beliefs[edge.key]
		if belief.lowerOK > 0 {
			candidateAddAmount(
				&hints, seen, belief.lowerOK,
				minimum, maximum,
			)
		}
		if belief.estimate > 0 {
			candidateAddAmount(
				&hints, seen, belief.estimate*7/8,
				minimum, maximum,
			)
		}
		if belief.upperFail > 0 {
			candidateAddAmount(
				&hints, seen, belief.upperFail/2,
				minimum, maximum,
			)
		}
	}

	for _, failure := range r.currentFails {
		if failure.upper == 0 {
			continue
		}
		candidateAddAmount(
			&hints, seen, failure.upper/2, minimum, maximum,
		)
		candidateAddAmount(
			&hints, seen, failure.upper/3, minimum, maximum,
		)
	}

	sort.Slice(hints, func(i, j int) bool {
		return hints[i] > hints[j]
	})
	if len(hints) > 8 {
		hints = hints[:8]
	}
	return hints
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if remaining <= 0 {
		return nil
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining
	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&sizes, seen, remaining, minimum, maximum,
	)
	if slots <= 1 {
		return sizes
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddAmount(
		&sizes, seen, base, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*3/4, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, base*5/4, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, remaining/2, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, remaining/3, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, remaining*2/3, minimum, maximum,
	)

	if r.shardCeiling > 0 {
		candidateAddAmount(
			&sizes, seen, r.shardCeiling, minimum, maximum,
		)
	}
	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/3,
			minimum, maximum,
		)
	}

	for _, hint := range r.evidenceHints(minimum, maximum) {
		candidateAddAmount(
			&sizes, seen, hint, minimum, maximum,
		)
	}

	if len(sizes) > 14 {
		sizes = sizes[:14]
	}
	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi, complete bool) float64 {

	score := 0.0
	for key, amount := range reservations {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, amount)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)
	var sent lnwire.MilliSatoshi

	for _, rt := range routes {
		finalAmount := candidateFinalAmount(rt)
		sent += finalAmount
		if rt.TotalAmount > finalAmount {
			fees += rt.TotalAmount - finalAmount
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 4_000_000
	if len(routes) > 1 {
		score -= 0.055 * float64(len(routes)-1)
	}

	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.075 * float64(count-1)
		}
	}

	if !complete && total > 0 {
		progress := float64(sent) / float64(total)
		if progress > 1 {
			progress = 1
		}
		score += 0.72 * progress
	}

	return score
}

func (r *candidateRouter) wasTried(rt *route.Route) bool {
	key := candidateAttemptKey{
		routeHash: candidateRouteHash(rt),
		amount:    candidateFinalAmount(rt),
	}
	return r.tried[key] > 0
}

func (r *candidateRouter) buildJointPlan(
	total lnwire.MilliSatoshi, parts int) ([]*route.Route, float64, bool) {

	const (
		beamWidth       = 9
		routesPerAmount = 3
	)

	if total <= 0 || parts <= 0 {
		return nil, 0, false
	}
	if parts > 10 {
		parts = 10
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(r.reserved),
	}}

	var best []*route.Route
	bestScore := math.Inf(-1)

	for depth := 0; depth < parts && len(states) > 0; depth++ {
		var incomplete []candidatePlanState

		for _, state := range states {
			sizes := r.shardSizes(state.remaining, state.slots)
			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				choices := r.topRoutes(size, routesPerAmount)

				for _, choice := range choices {
					if r.wasTried(choice.route) {
						continue
					}

					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserveInto(
						reservations, choice.route,
					)

					routes := append(
						append(
							[]*route.Route(nil),
							state.routes...,
						),
						choice.route,
					)
					remaining := state.remaining - size
					slots := state.slots - 1
					complete := remaining == 0

					next := candidatePlanState{
						remaining:    remaining,
						slots:        slots,
						routes:       routes,
						reservations: reservations,
					}
					next.score = r.planScore(
						routes, reservations, total,
						complete,
					)
					if math.IsInf(next.score, -1) {
						continue
					}

					if complete {
						if best == nil ||
							next.score > bestScore {

							best = routes
							bestScore = next.score
						}
						continue
					}

					if slots > 0 {
						incomplete = append(
							incomplete, next,
						)
					}
				}
			}
		}

		sort.Slice(incomplete, func(i, j int) bool {
			return incomplete[i].score >
				incomplete[j].score
		})
		if len(incomplete) > beamWidth {
			incomplete = incomplete[:beamWidth]
		}
		states = incomplete
	}

	return best, bestScore, best != nil
}

func (r *candidateRouter) partialSizes(
	total lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if total <= 1 {
		return nil
	}

	minimum := total / 32
	if minimum < 1 {
		minimum = 1
	}
	maximum := total - 1

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	if r.shardCeiling > 0 {
		candidateAddAmount(
			&sizes, seen, r.shardCeiling, minimum, maximum,
		)
	}
	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/3,
			minimum, maximum,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/4,
			minimum, maximum,
		)
	}

	candidateAddAmount(
		&sizes, seen, total*3/4, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, total/2, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, total/3, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, total/4, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, total/8, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, total/16, minimum, maximum,
	)
	candidateAddAmount(
		&sizes, seen, total/32, minimum, maximum,
	)

	for _, hint := range r.evidenceHints(minimum, maximum) {
		candidateAddAmount(
			&sizes, seen, hint, minimum, maximum,
		)
	}

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] > sizes[j]
	})
	return sizes
}

func (r *candidateRouter) bestPartial(
	total lnwire.MilliSatoshi) (*route.Route, error) {

	var best *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range r.partialSizes(total) {
		fraction := float64(size) / float64(total)
		for _, choice := range r.topRoutes(size, 3) {
			if r.wasTried(choice.route) {
				continue
			}

			utility := choice.logProb +
				1.15*math.Log(fraction)

			finalAmount := candidateFinalAmount(choice.route)
			if choice.route.TotalAmount > finalAmount {
				fee := choice.route.TotalAmount - finalAmount
				utility -= float64(fee) / 4_000_000
			}

			if best == nil || utility > bestUtility {
				best = choice.route
				bestUtility = utility
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if total <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	fullChoices := r.topRoutes(total, 1)
	if len(fullChoices) > 0 {
		full := fullChoices[0]
		if !r.wasTried(full.route) &&
			full.logProb >= math.Log(0.78) &&
			len(r.currentFails) == 0 {

			return []*route.Route{full.route}, nil
		}
	}

	if parts > 1 {
		plan, _, ok := r.buildJointPlan(total, int(parts))
		if ok {
			return plan, nil
		}
	}

	if len(fullChoices) > 0 && !r.wasTried(fullChoices[0].route) {
		return []*route.Route{fullChoices[0].route}, nil
	}

	partial, err := r.bestPartial(total)
	if err != nil {
		return nil, err
	}
	return []*route.Route{partial}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}

	attemptKey := candidateAttemptKey{
		routeHash: candidateRouteHash(rt),
		amount:    candidateFinalAmount(rt),
	}
	r.tried[attemptKey]++
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt &&
			!r.wasTried(rt) {

			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil {
		highEstimate := edge.capacity * 7 / 8
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt / 3
	if edge := r.edges[key]; edge != nil {
		depletedEstimate := edge.capacity / 20
		if estimate > depletedEstimate {
			estimate = depletedEstimate
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) noteFailedShard(rt *route.Route) {
	amount := candidateFinalAmount(rt)
	if amount <= 0 {
		return
	}

	r.lastFailedShard = amount
	ceiling := amount * 5 / 8
	if ceiling <= 0 {
		ceiling = 1
	}
	if r.shardCeiling == 0 || ceiling < r.shardCeiling {
		r.shardCeiling = ceiling
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amount+r.reserved[key])
		}

		r.held = append(r.held, rt)
		return nil
	}

	r.planned = nil
	r.noteFailedShard(rt)

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passed := failIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amountOverEdge, ok := candidateRouteAmount(rt, failIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amountOverEdge + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key           candidateEdgeKey
	capacity      lnwire.MilliSatoshi
	baseFee       lnwire.MilliSatoshi
	feeRate       lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feeRate/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[candidateEdgeKey]*candidateEdge

	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	failures map[candidateEdgeKey]candidateFailure
	blocked  map[candidateEdgeKey]bool
	suspect  map[candidateEdgeKey]uint32
	uses     map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailed lnwire.MilliSatoshi
	attempts   int
	maxAttempts int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFee) + uint64(e.feeRate)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incoming:      make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		localSpent:    make(map[uint64]lnwire.MilliSatoshi),
		beliefs:       make(map[candidateEdgeKey]candidateBelief),
		failures:      make(map[candidateEdgeKey]candidateFailure),
		blocked:       make(map[candidateEdgeKey]bool),
		suspect:       make(map[candidateEdgeKey]uint32),
		uses:          make(map[candidateEdgeKey]uint32),
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.maxAttempts = 14 + 3*int(maxParts)
	if r.maxAttempts < 18 {
		r.maxAttempts = 18
	}
	if r.maxAttempts > 32 {
		r.maxAttempts = 32
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFee: policy.FeeBaseMSat,
					feeRate: policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC: policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incoming[node] = append(r.incoming[node], edge)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if amt <= 0 || capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.05)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.033))
	p := 0.47*lowMode + 0.53*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.989 {
		return 0.989
	}
	return p
}

func (r *candidateRouter) localAvailable(chanID uint64) lnwire.MilliSatoshi {
	balance, ok := r.localBalances[chanID]
	if !ok {
		return 0
	}
	spent := r.localSpent[chanID]
	if spent >= balance {
		return 0
	}
	return balance - spent
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity || r.blocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if total > r.localAvailable(edge.key.chanID) {
			return 0
		}
		return 0.9995
	}

	retryScale := 1.0
	if failure, ok := r.failures[edge.key]; ok && failure.upper > 0 {
		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.80:
			retryScale = 0.015
		case ratio > 0.67:
			retryScale = 0.07
		case ratio > 0.53:
			retryScale = 0.20
		case ratio > 0.40:
			retryScale = 0.42
		case ratio > 0.27:
			retryScale = 0.66
		default:
			retryScale = 0.87
		}
		if failure.count >= 2 {
			retryScale *= 0.72
		}
		if failure.count >= 4 {
			retryScale *= 0.60
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if ok {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.996

		case belief.upperFail > 0 && total >= belief.upperFail:
			p = 0.005

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK:

			width := float64(belief.upperFail - belief.lowerOK)
			position := float64(total-belief.lowerOK) / width
			if position < 0 {
				position = 0
			}
			if position > 1 {
				position = 1
			}
			evidence := 0.994 - 0.988*position
			p = 0.08*p + 0.92*evidence

		case belief.upperFail > 0:
			ratio := float64(total) / float64(belief.upperFail)
			if ratio > 0.18 {
				scale := 1 - 0.94*(ratio-0.18)/0.82
				if scale < 0.05 {
					scale = 0.05
				}
				p *= scale
			}

		case belief.lowerOK > 0:
			distance := float64(total-belief.lowerOK) /
				float64(edge.capacity)
			if distance > 0 {
				boost := 0.68 * math.Exp(-distance/0.18)
				p += boost * (1 - p)
			}
		}

		if belief.estimate > 0 {
			scale := 0.065 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			estimateP := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate))/scale,
			))
			weight := 0.22
			if belief.successes+belief.failures >= 3 {
				weight = 0.34
			}
			p = (1-weight)*p + weight*estimateP
		}
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}
	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}
	return r.liquidityProbability(edge, reserved+amt)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 310_000.0
		hopPenalty = 7_500.0
	)

	best := map[route.Vertex]float64{r.spec.Target: 0}
	next := make(map[route.Vertex]*candidateEdge)
	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := best[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}
		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incoming[item.node] {
			overEdge := item.required
			p := r.edgeProbability(edge, overEdge)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(overEdge)
			}
			sending := overEdge + fee

			score := item.score + float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty +
				float64(r.uses[edge.key])*18_000 +
				float64(r.suspect[edge.key])*95_000

			if extra != nil {
				score += extra[edge.key]
			}
			if r.reserved[edge.key] > 0 &&
				edge.key.from != r.source {

				score += 50_000
			}

			old, found := best[edge.key.from]
			if found && score >= old {
				continue
			}

			best[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := best[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken route at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] + outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)
		if i < last {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}
		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route,
	index int) (lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return 0, false
	}
	if index == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[index-1].AmtToForward, true
}

func candidateRouteKey(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}
	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}
	h := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i := range rt.Hops {
		key, ok := candidateRouteKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(
			key.chanID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		h ^= candidateMix64(candidateVertexHash(key.to))
	}
	return candidateMix64(h)
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) settleHeldLocally() {
	for _, rt := range r.held {
		if rt == nil || len(rt.Hops) == 0 {
			continue
		}
		amount, ok := candidateRouteAmount(rt, 0)
		if ok {
			r.localSpent[rt.Hops[0].ChannelID] += amount
		}
	}
	r.held = nil
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.settleHeldLocally()
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	for _, rt := range r.held[len(r.held)-count:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}
	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	for _, pair := range [][2]int64{
		{1, 2}, {2, 3}, {4, 5}, {1, 1},
		{6, 5}, {3, 2}, {2, 1},
	} {
		value := base * lnwire.MilliSatoshi(pair[0]) /
			lnwire.MilliSatoshi(pair[1])
		candidateAddAmount(
			&values, seen, value, minimum, maximum,
		)
	}

	if slots == 2 {
		for numerator := int64(1); numerator <= 4; numerator++ {
			value := remaining * lnwire.MilliSatoshi(numerator) / 5
			candidateAddAmount(
				&values, seen, value, minimum, maximum,
			)
		}
	}

	if r.lastFailed > 0 {
		for _, pair := range [][2]int64{
			{1, 5}, {1, 4}, {1, 3}, {2, 5},
			{1, 2}, {3, 5}, {2, 3},
		} {
			value := r.lastFailed *
				lnwire.MilliSatoshi(pair[0]) /
				lnwire.MilliSatoshi(pair[1])
			candidateAddAmount(
				&values, seen, value, minimum, maximum,
			)
		}
	}

	for key, failure := range r.failures {
		if failure.upper == 0 {
			continue
		}
		edge := r.edges[key]
		if edge == nil {
			continue
		}
		for _, pair := range [][2]int64{{1, 4}, {2, 5}, {1, 2}} {
			value := failure.upper *
				lnwire.MilliSatoshi(pair[0]) /
				lnwire.MilliSatoshi(pair[1])
			candidateAddAmount(
				&values, seen, value, minimum, maximum,
			)
		}
	}

	for key, belief := range r.beliefs {
		edge := r.edges[key]
		if edge == nil ||
			(edge.key.from != r.source &&
				edge.key.to != r.spec.Target) {

			continue
		}
		if belief.lowerOK > 0 {
			candidateAddAmount(
				&values, seen, belief.lowerOK,
				minimum, maximum,
			)
		}
		if belief.upperFail > 0 {
			candidateAddAmount(
				&values, seen, belief.upperFail*2/5,
				minimum, maximum,
			)
		}
	}

	sort.SliceStable(values, func(i, j int) bool {
		di := math.Abs(float64(values[i] - base))
		dj := math.Abs(float64(values[j] - base))
		return di < dj
	})

	const maxCandidates = 18
	if len(values) > maxCandidates {
		values = values[:maxCandidates]
	}
	return values
}

type candidateRouteOption struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeOptions(
	amt lnwire.MilliSatoshi) []candidateRouteOption {

	const optionCount = 4

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	var options []candidateRouteOption

	for option := 0; option < optionCount; option++ {
		rt, logProb, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			options = append(options, candidateRouteOption{
				route:   rt,
				logProb: logProb,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteKey(rt, i)
			if !ok {
				continue
			}
			penalty := 850_000.0
			if key.from == r.source {
				penalty = 260_000
			}
			penalties[key] += penalty
		}
	}

	return options
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi, complete bool) float64 {

	score := 0.0
	for key, amount := range reservations {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}
		p := r.liquidityProbability(edge, amount)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)
	for _, rt := range routes {
		finalAmount := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmount {
			fees += rt.TotalAmount - finalAmount
		}
		for i := range rt.Hops {
			key, ok := candidateRouteKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 4_500_000
	if len(routes) > 1 {
		score -= 0.06 * float64(len(routes)-1)
	}
	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.14 * float64(count-1)
		}
	}

	if !complete && total > 0 {
		remaining := total
		for _, rt := range routes {
			remaining -= candidateFinalAmount(rt)
		}
		progress := 1 - float64(remaining)/float64(total)
		score += 0.32 * progress
	}

	return score
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 9

	saved := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = saved
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(r.reserved),
	}}

	for depth := 0; depth < parts; depth++ {
		var expanded []candidatePlanState

		for _, state := range states {
			for _, size := range r.shardSizes(
				state.remaining, state.slots,
			) {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				for _, option := range r.routeOptions(size) {
					remaining := state.remaining - size
					slots := state.slots - 1
					if remaining < 0 ||
						((remaining == 0) != (slots == 0)) {

						continue
					}

					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserveInto(
						reservations, option.route,
					)

					routes := append(
						append(
							[]*route.Route(nil),
							state.routes...,
						),
						option.route,
					)

					next := candidatePlanState{
						remaining:    remaining,
						slots:        slots,
						routes:       routes,
						reservations: reservations,
					}
					next.score = r.planScore(
						routes, reservations, total,
						remaining == 0,
					)
					if !math.IsInf(next.score, -1) {
						expanded = append(expanded, next)
					}
				}
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.SliceStable(expanded, func(i, j int) bool {
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	for _, state := range states {
		if state.remaining == 0 && state.slots == 0 {
			return state.routes, state.score, true
		}
	}
	return nil, 0, false
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	full, fullLogProb, fullErr := r.findRoute(total, nil)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	if fullErr == nil && fullLogProb >= math.Log(0.94) &&
		r.lastFailed == 0 {

		return []*route.Route{full}, nil
	}

	maxPlanParts := int(parts)
	if maxPlanParts > 8 {
		maxPlanParts = 8
	}
	if lnwire.MilliSatoshi(maxPlanParts) > total {
		maxPlanParts = int(total)
	}
	if maxPlanParts < 1 {
		return nil, errors.New("payment amount too small")
	}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(r.reserved)
		candidateReserveInto(reservations, full)
		bestPlan = []*route.Route{full}
		bestScore = r.planScore(
			bestPlan, reservations, total, true,
		)
	}

	for count := 2; count <= maxPlanParts; count++ {
		plan, score, ok := r.planWithParts(total, count)
		if ok && (bestPlan == nil || score > bestScore) {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}
	return bestPlan, nil
}

func (r *candidateRouter) routeFits(rt *route.Route) bool {
	added := make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	for i := range rt.Hops {
		key, ok := candidateRouteKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil || r.blocked[key] {
			return false
		}

		amount, ok := candidateRouteAmount(rt, i)
		if !ok || !edge.policyAllows(amount) {
			return false
		}

		added[key] += amount
		total := r.reserved[key] + added[key]
		if total > edge.capacity {
			return false
		}
		if key.from == r.source &&
			total > r.localAvailable(key.chanID) {

			return false
		}
		if failure, ok := r.failures[key]; ok &&
			failure.upper > 0 && total >= failure.upper {

			return false
		}
	}
	return true
}

func (r *candidateRouter) recordUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteKey(rt, i)
		if ok {
			r.uses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.maxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt && r.routeFits(rt) {
			r.planned = r.planned[1:]
			r.recordUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	r.planned = nil
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	}

	r.recordUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	if failure, ok := r.failures[key]; ok &&
		failure.upper > 0 && amount >= failure.upper {

		delete(r.failures, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amount > belief.lowerOK {
		belief.lowerOK = amount
	}
	if belief.upperFail > 0 && amount >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amount
	if edge := r.edges[key]; edge != nil {
		high := edge.capacity * 17 / 20
		if high > estimate {
			estimate = high
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	current := r.failures[key]
	if current.upper == 0 || amount < current.upper {
		current.upper = amount
	}
	current.count++
	r.failures[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amount < belief.upperFail {
		belief.upperFail = amount
	}
	if belief.lowerOK >= amount {
		belief.lowerOK = 0
	}

	estimate := amount / 4
	if edge := r.edges[key]; edge != nil {
		floor := edge.capacity / 20
		if estimate > floor {
			estimate = floor
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amount ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markSuspect(rt *route.Route, weight uint32) {
	for i := range rt.Hops {
		key, ok := candidateRouteKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if ok {
				r.learnSuccess(key, amount+r.reserved[key])
			}
		}
		r.held = append(r.held, rt)
		r.lastFailed = 0
		return nil
	}

	r.planned = nil
	r.lastFailed = candidateFinalAmount(rt)

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markSuspect(rt, 2)
		return nil
	}

	passed := failureIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markSuspect(rt, 2)
		return nil
	}

	key, ok := candidateRouteKey(rt, failureIndex)
	if !ok {
		r.markSuspect(rt, 2)
		return nil
	}
	amount, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markSuspect(rt, 2)
		return nil
	}
	totalRequired := amount + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:
		r.blocked[key] = true
		r.suspect[key] += 4

	default:
		r.suspect[key] += 3
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	balances := make(map[uint64]lnwire.MilliSatoshi, len(localBalances))
	for chanID, balance := range localBalances {
		balances[chanID] = balance
	}

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  balances,
		localSpent:     make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 4
	if r.attemptLimit < 8 {
		r.attemptLimit = 8
	}
	if r.attemptLimit > 28 {
		r.attemptLimit = 28
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.05)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.032))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.988 {
		return 0.988
	}
	return p
}

func (r *candidateRouter) localAvailable(chanID uint64) (
	lnwire.MilliSatoshi, bool) {

	balance, ok := r.localBalances[chanID]
	if !ok {
		return 0, false
	}

	spent := r.localSpent[chanID]
	if spent >= balance {
		return 0, true
	}
	return balance - spent, true
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		available, ok := r.localAvailable(edge.key.chanID)
		if !ok || total > available {
			return 0
		}
		return 0.9995
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case failure.count >= 3 && ratio > 0.24:
			return 0
		case failure.count >= 2 && ratio > 0.40:
			return 0
		case ratio > 0.72:
			return 0
		case ratio > 0.55:
			retryScale = 0.13
		case ratio > 0.38:
			retryScale = 0.31
		case ratio > 0.23:
			retryScale = 0.55
		default:
			retryScale = 0.78
		}

		if failure.count >= 2 {
			retryScale *= 0.58
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.005

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		evidence := 0.993 - 0.987*position
		p = 0.10*p + 0.90*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.28 {
			scale := 1 - 0.95*(ratio-0.28)/0.72
			if scale < 0.05 {
				scale = 0.05
			}
			p *= scale
		}

	case belief.lowerOK > 0 && total > belief.lowerOK:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.68 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.075 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateProb := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.26
		evidenceCount := belief.successes + belief.failures
		if evidenceCount >= 3 {
			weight = 0.38
		}
		if evidenceCount >= 7 {
			weight = 0.46
		}
		p = (1-weight)*p + weight*estimateProb
	}

	p *= retryScale
	if p < 0.0015 {
		return 0.0015
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := reservations[edge.key]
	if reserved >= edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	return r.liquidityProbability(edge, reserved+amt)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	hops     int
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) shortestRoute(amt lnwire.MilliSatoshi,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]uint32) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight      = 700_000.0
		hopPenalty      = 1_500.0
		diversityWeight = 240_000.0
		reservedPenalty = 130_000.0
		suspectPenalty  = 420_000.0
		maxRouteHops    = 20
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64
	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}
		if item.hops >= maxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOverEdge := item.required
			p := r.probability(edge, amountOverEdge, reservations)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			sending := amountOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(diversity[edge.key]) *
				diversityWeight
			edgeScore += float64(r.suspect[edge.key]) *
				suspectPenalty

			if reservations[edge.key] > 0 {
				edgeScore += reservedPenalty
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				hops:     item.hops + 1,
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	return r.buildFixedRoute(amt, path)
}

func (r *candidateRouter) buildFixedRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 || len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amountOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amountOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amountOver[i] = amountOver[i+1] +
			forwardingEdge.fee(amountOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amountOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amountOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i, hop := range rt.Hops {
		x := candidateMix64(hop.ChannelID + uint64(i+1))
		x ^= candidateMix64(candidateVertexHash(hop.PubKeyBytes))
		h = candidateMix64(h ^ x)
	}
	return h
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amount := range src {
		dst[key] = amount
	}
	return dst
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	if rt == nil {
		return
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) pathFromRoute(rt *route.Route) (
	[]*candidateEdge, bool) {

	if rt == nil {
		return nil, false
	}

	path := make([]*candidateEdge, 0, len(rt.Hops))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return nil, false
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, false
		}
		path = append(path, edge)
	}
	return path, true
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeAlternatives(
	amt lnwire.MilliSatoshi,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	limit int) []candidateRouteChoice {

	if limit < 1 {
		limit = 1
	}

	diversity := make(map[candidateEdgeKey]uint32)
	seen := make(map[uint64]bool)
	choices := make([]candidateRouteChoice, 0, limit)

	maxTries := limit * 4
	for tries := 0; tries < maxTries && len(choices) < limit; tries++ {
		rt, logProb, err := r.shortestRoute(
			amt, reservations, diversity,
		)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				logProb: logProb,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				diversity[key]++
			}
		}
	}

	return choices
}

func (r *candidateRouter) routeQuality(rt *route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi) bool {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil {
			return false
		}

		amount, ok := candidateRouteAmount(rt, i)
		if !ok {
			return false
		}
		p := r.probability(edge, amount, reservations)
		if p < 0.10 {
			return false
		}
	}
	return true
}

func (r *candidateRouter) pathOffer(rt *route.Route,
	maximum lnwire.MilliSatoshi,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi) (
	lnwire.MilliSatoshi, *route.Route) {

	path, ok := r.pathFromRoute(rt)
	if !ok || maximum <= 0 {
		return 0, nil
	}

	anchor := candidateFinalAmount(rt)
	if anchor > maximum {
		anchor = maximum
	}

	var anchorRoute *route.Route
	for anchor > 0 {
		candidate, err := r.buildFixedRoute(anchor, path)
		if err == nil && r.routeQuality(candidate, reservations) {
			anchorRoute = candidate
			break
		}
		anchor /= 2
	}
	if anchorRoute == nil || anchor <= 0 {
		return 0, nil
	}

	low := anchor
	high := maximum
	for low < high {
		mid := low + (high-low+1)/2
		candidate, err := r.buildFixedRoute(mid, path)
		if err == nil && r.routeQuality(candidate, reservations) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	offer := low * 9 / 10
	if offer < anchor {
		offer = anchor
	}
	offeredRoute, err := r.buildFixedRoute(offer, path)
	if err != nil {
		return 0, nil
	}
	return offer, offeredRoute
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	maximum lnwire.MilliSatoshi) {

	if value <= 0 || maximum <= 0 {
		return
	}
	if value > maximum {
		value = maximum
	}
	if seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	ideal := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	values := make([]lnwire.MilliSatoshi, 0, 9)
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&values, seen, remaining, remaining)
	candidateAddAmount(&values, seen, ideal, remaining)
	candidateAddAmount(&values, seen, ideal*3/4, remaining)
	candidateAddAmount(&values, seen, ideal*5/4, remaining)
	candidateAddAmount(&values, seen, ideal*3/2, remaining)
	candidateAddAmount(&values, seen, ideal*2, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/3, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/4, remaining,
		)
	}

	return values
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi, complete bool) float64 {

	score := 0.0
	for key, amount := range reservations {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, amount)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
		score -= 0.12 * float64(r.suspect[key])
	}

	var fees lnwire.MilliSatoshi
	var sent lnwire.MilliSatoshi
	for _, rt := range routes {
		finalAmount := candidateFinalAmount(rt)
		sent += finalAmount
		if rt.TotalAmount > finalAmount {
			fees += rt.TotalAmount - finalAmount
		}
	}

	score -= float64(fees) / 10_000_000
	if len(routes) > 1 {
		score -= 0.035 * float64(len(routes)-1)
	}

	if !complete && total > 0 {
		progress := float64(sent) / float64(total)
		score += 0.72 * progress
	}

	return score
}

func (r *candidateRouter) extendPlan(state candidatePlanState,
	rt *route.Route, total lnwire.MilliSatoshi) (
	candidatePlanState, bool) {

	amount := candidateFinalAmount(rt)
	if amount <= 0 || amount > state.remaining || state.slots <= 0 {
		return candidatePlanState{}, false
	}

	reservations := candidateCopyReservations(state.reservations)
	candidateReserveInto(reservations, rt)

	routes := append(
		append([]*route.Route(nil), state.routes...), rt,
	)
	next := candidatePlanState{
		remaining:    state.remaining - amount,
		slots:        state.slots - 1,
		routes:       routes,
		reservations: reservations,
	}

	if next.remaining > 0 && next.slots == 0 {
		return candidatePlanState{}, false
	}

	next.score = r.planScore(
		routes, reservations, total, next.remaining == 0,
	)
	if math.IsInf(next.score, -1) {
		return candidatePlanState{}, false
	}

	return next, true
}

func (r *candidateRouter) completePlan(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, bool) {

	const (
		beamWidth       = 9
		alternatives    = 4
		maxPlanningPart = 10
	)

	if parts > maxPlanningPart {
		parts = maxPlanningPart
	}
	if parts < 1 {
		return nil, false
	}

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(r.reserved),
	}}

	var best []*route.Route
	bestScore := math.Inf(-1)

	for depth := 0; depth < parts && len(states) > 0; depth++ {
		var expanded []candidatePlanState

		for _, state := range states {
			sizes := r.shardSizes(state.remaining, state.slots)
			added := make(map[uint64]bool)

			for _, size := range sizes {
				choices := r.routeAlternatives(
					size, state.reservations, alternatives,
				)

				for _, choice := range choices {
					hash := candidateRouteHash(choice.route) ^
						candidateMix64(uint64(size))
					if !added[hash] {
						added[hash] = true
						next, ok := r.extendPlan(
							state, choice.route, total,
						)
						if ok {
							if next.remaining == 0 {
								if next.score > bestScore {
									bestScore = next.score
									best = next.routes
								}
							} else {
								expanded = append(
									expanded, next,
								)
							}
						}
					}

					offer, offeredRoute := r.pathOffer(
						choice.route, state.remaining,
						state.reservations,
					)
					if offeredRoute == nil || offer == size {
						continue
					}

					offerHash := candidateRouteHash(offeredRoute) ^
						candidateMix64(uint64(offer))
					if added[offerHash] {
						continue
					}
					added[offerHash] = true

					next, ok := r.extendPlan(
						state, offeredRoute, total,
					)
					if !ok {
						continue
					}
					if next.remaining == 0 {
						if next.score > bestScore {
							bestScore = next.score
							best = next.routes
						}
					} else {
						expanded = append(expanded, next)
					}
				}
			}
		}

		sort.Slice(expanded, func(i, j int) bool {
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	return best, best != nil
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts <= 1 {
		return nil, errors.New("no route found")
	}

	values := make([]lnwire.MilliSatoshi, 0, 8)
	seen := make(map[lnwire.MilliSatoshi]bool)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard/2, total,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/3, total,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/4, total,
		)
	}

	candidateAddAmount(&values, seen, total/2, total)
	candidateAddAmount(&values, seen, total/3, total)
	candidateAddAmount(
		&values, seen, total/lnwire.MilliSatoshi(parts), total,
	)
	candidateAddAmount(&values, seen, total/4, total)
	candidateAddAmount(&values, seen, total*3/4, total)

	var best *route.Route
	bestScore := math.Inf(-1)

	for _, size := range values {
		choices := r.routeAlternatives(size, r.reserved, 5)
		for _, choice := range choices {
			finalAmount := candidateFinalAmount(choice.route)
			if finalAmount <= 0 {
				continue
			}

			fees := choice.route.TotalAmount - finalAmount
			progress := float64(finalAmount) / float64(total)
			score := choice.logProb + 1.25*progress -
				float64(fees)/10_000_000

			if score > bestScore {
				bestScore = score
				best = choice.route
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	if plan, ok := r.completePlan(total, int(parts)); ok {
		return plan, nil
	}

	fallback, err := r.fallbackShard(total, parts)
	if err != nil {
		return nil, err
	}
	return []*route.Route{fallback}, nil
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) commitLocalRoute(rt *route.Route) {
	if rt == nil || len(rt.Hops) == 0 {
		return
	}

	key, ok := candidateRouteEdgeKey(rt, 0)
	if !ok || key.from != r.source {
		return
	}
	amount, ok := candidateRouteAmount(rt, 0)
	if ok {
		r.localSpent[key.chanID] += amount
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) bool {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if len(r.held) == 0 {
		return false
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}

	settledCount := len(r.held) - count
	settled := settledCount > 0
	for _, rt := range r.held[:settledCount] {
		r.commitLocalRoute(rt)
	}

	r.held = append([]*route.Route(nil), r.held[settledCount:]...)
	for _, rt := range r.held {
		r.reserveRoute(rt)
	}

	return settled
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	settled := r.syncReservations(inFlightHtlcs)
	if settled {
		r.planned = nil
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt {
			r.planned = r.planned[1:]
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil {
		highEstimate := edge.capacity * 7 / 8
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt / 3
	if edge := r.edges[key]; edge != nil {
		depletedEstimate := edge.capacity / 18
		if estimate > depletedEstimate {
			estimate = depletedEstimate
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	if rt == nil {
		return
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amount+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amountOver, ok := candidateRouteAmount(rt, failIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amountOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3
		r.lastFailedShard = candidateFinalAmount(rt)

	default:
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key           candidateEdgeKey
	capacity      lnwire.MilliSatoshi
	baseFee       lnwire.MilliSatoshi
	feeRate       lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feeRate/1_000_000
}

func (e *candidateEdge) allows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming      map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	failures      map[candidateEdgeKey]candidateFailure
	policyBlocked map[candidateEdgeKey]bool
	suspect       map[candidateEdgeKey]uint32
	edgeUses      map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailed lnwire.MilliSatoshi
	attempts   int
	limit      int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFee) + uint64(e.feeRate)<<17)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incoming:       make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		failures:       make(map[candidateEdgeKey]candidateFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		suspect:        make(map[candidateEdgeKey]uint32),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.limit = 20 + 5*int(maxParts)
	if r.limit < 28 {
		r.limit = 28
	}
	if r.limit > 64 {
		r.limit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee:       policy.FeeBaseMSat,
					feeRate:       policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incoming[node] = append(r.incoming[node], edge)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if amt <= 0 || capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	low := math.Exp(-x / 0.040)
	high := 1 / (1 + math.Exp((x-0.91)/0.032))
	p := 0.46*low + 0.54*high

	if p < 0.004 {
		return 0.004
	}
	if p > 0.989 {
		return 0.989
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity || r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	retryScale := 1.0
	if failure, ok := r.failures[edge.key]; ok && failure.upper > 0 {
		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.78:
			retryScale = 0.02
		case ratio > 0.62:
			retryScale = 0.09
		case ratio > 0.48:
			retryScale = 0.23
		case ratio > 0.34:
			retryScale = 0.45
		case ratio > 0.20:
			retryScale = 0.70
		default:
			retryScale = 0.88
		}
		if failure.count >= 2 {
			retryScale *= 0.70
		}
		if failure.count >= 4 {
			retryScale *= 0.55
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.005

	case belief.lowerOK > 0 && belief.upperFail > belief.lowerOK:
		position := float64(total-belief.lowerOK) /
			float64(belief.upperFail-belief.lowerOK)
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}
		evidence := 0.995 - 0.990*position
		p = 0.08*p + 0.92*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.18 {
			scale := 1 - 0.94*(ratio-0.18)/0.82
			if scale < 0.05 {
				scale = 0.05
			}
			p *= scale
		}

	case belief.lowerOK > 0:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.72 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := math.Max(1, 0.065*float64(edge.capacity))
		estimateP := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		weight := 0.25
		if belief.successes+belief.failures >= 3 {
			weight = 0.38
		}
		p = (1-weight)*p + weight*estimateP
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.allows(amt) {
		return 0
	}

	total := r.reserved[edge.key] + amt
	if total < amt || total > edge.capacity {
		return 0
	}

	return r.liquidityProbability(edge, total)
}

type candidateSearchState struct {
	node     route.Vertex
	required lnwire.MilliSatoshi
	score    float64
	logProb  float64
	path     []*candidateEdge
	index    int
}

type candidateSearchQueue []*candidateSearchState

func (q candidateSearchQueue) Len() int {
	return len(q)
}

func (q candidateSearchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateSearchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateSearchQueue) Push(value any) {
	item := value.(*candidateSearchState)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateSearchQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

type candidateLabel struct {
	required lnwire.MilliSatoshi
	score    float64
}

func candidateDominated(labels []candidateLabel,
	required lnwire.MilliSatoshi, score float64) bool {

	for _, label := range labels {
		if label.required <= required && label.score <= score {
			return true
		}
	}
	return false
}

func candidateAddLabel(labels []candidateLabel,
	required lnwire.MilliSatoshi, score float64) []candidateLabel {

	out := labels[:0]
	for _, label := range labels {
		if required <= label.required && score <= label.score {
			continue
		}
		out = append(out, label)
	}
	out = append(out, candidateLabel{
		required: required,
		score:    score,
	})

	sort.Slice(out, func(i, j int) bool {
		return out[i].score < out[j].score
	})
	if len(out) > 10 {
		out = out[:10]
	}
	return out
}

func candidatePathContains(path []*candidateEdge, node route.Vertex) bool {
	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}
	return false
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	penalties map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight    = 285_000.0
		hopPenalty    = 750.0
		maxHops       = 16
		maxExpansions = 50000
	)

	queue := &candidateSearchQueue{}
	heap.Push(queue, &candidateSearchState{
		node:     r.spec.Target,
		required: amt,
	})

	labels := make(map[route.Vertex][]candidateLabel)
	labels[r.spec.Target] = []candidateLabel{{
		required: amt,
		score:    0,
	}}

	expansions := 0
	for queue.Len() > 0 && expansions < maxExpansions {
		state := heap.Pop(queue).(*candidateSearchState)
		expansions++

		if state.node == r.source {
			rt, err := r.buildRoute(amt, state.path)
			return rt, state.logProb, err
		}
		if len(state.path) >= maxHops {
			continue
		}

		for _, edge := range r.incoming[state.node] {
			if candidatePathContains(state.path, edge.key.from) {
				continue
			}

			amountOverEdge := state.required
			p := r.probability(edge, amountOverEdge)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			required := amountOverEdge + fee
			if required < amountOverEdge {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.edgeUses[edge.key]) * 8_000
			edgeScore += float64(r.suspect[edge.key]) * 45_000
			if penalties != nil {
				edgeScore += penalties[edge.key]
			}

			score := state.score + edgeScore
			if candidateDominated(
				labels[edge.key.from], required, score,
			) {
				continue
			}

			labels[edge.key.from] = candidateAddLabel(
				labels[edge.key.from], required, score,
			)

			path := make([]*candidateEdge, len(state.path)+1)
			path[0] = edge
			copy(path[1:], state.path)

			heap.Push(queue, &candidateSearchState{
				node:     edge.key.from,
				required: required,
				score:    score,
				logProb:  state.logProb + math.Log(p),
				path:     path,
			})
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 || path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("invalid route path")
	}

	for i := 1; i < len(path); i++ {
		if path[i-1].key.to != path[i].key.from {
			return nil, errors.New("disconnected route path")
		}
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1

	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] + outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(finalCltvDelta)
		if i < last {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route,
	index int) (lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return 0, false
	}
	if index == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[index-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(
			key.chanID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		h ^= candidateMix64(candidateVertexHash(key.to))
	}
	return candidateMix64(h)
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	for _, rt := range r.held[len(r.held)-count:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}
	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)
	values := make([]lnwire.MilliSatoshi, 0, 28)
	seen := make(map[lnwire.MilliSatoshi]bool)

	for _, pair := range [][2]int64{
		{1, 1}, {3, 4}, {5, 4}, {1, 2}, {3, 2},
		{2, 1}, {1, 3}, {2, 3}, {4, 3},
	} {
		candidateAddAmount(
			&values, seen,
			base*lnwire.MilliSatoshi(pair[0])/
				lnwire.MilliSatoshi(pair[1]),
			minimum, maximum,
		)
	}

	if r.lastFailed > 0 {
		for _, pair := range [][2]int64{
			{1, 5}, {1, 4}, {1, 3}, {2, 5}, {1, 2}, {3, 5},
		} {
			candidateAddAmount(
				&values, seen,
				r.lastFailed*lnwire.MilliSatoshi(pair[0])/
					lnwire.MilliSatoshi(pair[1]),
				minimum, maximum,
			)
		}
	}

	for key, belief := range r.beliefs {
		edge := r.edges[key]
		if edge == nil {
			continue
		}
		reserved := r.reserved[key]

		if belief.lowerOK > reserved {
			candidateAddAmount(
				&values, seen, belief.lowerOK-reserved,
				minimum, maximum,
			)
		}
		if belief.estimate > reserved {
			candidateAddAmount(
				&values, seen, belief.estimate-reserved,
				minimum, maximum,
			)
		}
		if belief.upperFail > reserved {
			candidateAddAmount(
				&values, seen,
				(belief.upperFail-reserved)*2/5,
				minimum, maximum,
			)
		}
	}

	sort.SliceStable(values, func(i, j int) bool {
		di := math.Abs(math.Log(
			(float64(values[i]) + 1) / (float64(base) + 1),
		))
		dj := math.Abs(math.Log(
			(float64(values[j]) + 1) / (float64(base) + 1),
		))
		return di < dj
	})

	if len(values) > 18 {
		values = values[:18]
	}
	return values
}

type candidateRouteOption struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeOptions(
	amt lnwire.MilliSatoshi, count int) []candidateRouteOption {

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	options := make([]candidateRouteOption, 0, count)

	for len(options) < count {
		rt, logProb, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			options = append(options, candidateRouteOption{
				route:   rt,
				logProb: logProb,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			if key.from == r.source {
				penalties[key] += 170_000
			} else {
				penalties[key] += 520_000
			}
		}

		if len(seen) > count*2 {
			break
		}
	}
	return options
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        int
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi) float64 {

	score := 0.0
	for key, amount := range reservations {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, amount)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	sent := lnwire.MilliSatoshi(0)
	uses := make(map[candidateEdgeKey]uint32)

	for _, rt := range routes {
		finalAmount := candidateFinalAmount(rt)
		sent += finalAmount
		if rt.TotalAmount > finalAmount {
			fees += rt.TotalAmount - finalAmount
		}
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				uses[key]++
			}
		}
	}

	score -= float64(fees) / 5_000_000
	score -= 0.035 * float64(len(routes)-1)

	for key, count := range uses {
		if count > 1 && key.from != r.source {
			score -= 0.075 * float64(count-1)
		}
	}

	if total > 0 {
		score += 0.25 * float64(sent) / float64(total)
	}
	return score
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 12

	saved := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = saved
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(saved),
	}}

	for depth := 0; depth < parts; depth++ {
		expanded := make([]candidatePlanState, 0, beamWidth*8)

		for _, state := range states {
			for _, size := range r.shardSizes(
				state.remaining, state.slots,
			) {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				for _, option := range r.routeOptions(size, 4) {
					remaining := state.remaining - size
					slots := state.slots - 1
					if remaining < 0 {
						continue
					}
					if (remaining == 0) != (slots == 0) {
						continue
					}

					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserveInto(
						reservations, option.route,
					)

					routes := append(
						append([]*route.Route(nil), state.routes...),
						option.route,
					)
					score := r.planScore(
						routes, reservations, total,
					)
					if math.IsInf(score, -1) {
						continue
					}

					expanded = append(expanded, candidatePlanState{
						remaining:    remaining,
						slots:        slots,
						routes:       routes,
						reservations: reservations,
						score:        score,
					})
				}
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.SliceStable(expanded, func(i, j int) bool {
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	for _, state := range states {
		if state.remaining == 0 && state.slots == 0 {
			return state.routes, state.score, true
		}
	}
	return nil, 0, false
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	full, fullLogProb, fullErr := r.findRoute(total, nil)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	if fullErr == nil && fullLogProb >= math.Log(0.88) &&
		r.lastFailed == 0 {

		return []*route.Route{full}, nil
	}

	maxParts := int(parts)
	if maxParts > 10 {
		maxParts = 10
	}
	if lnwire.MilliSatoshi(maxParts) > total {
		maxParts = int(total)
	}

	var best []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(r.reserved)
		candidateReserveInto(reservations, full)
		best = []*route.Route{full}
		bestScore = r.planScore(best, reservations, total)
	}

	for count := 2; count <= maxParts; count++ {
		plan, score, ok := r.planWithParts(total, count)
		if ok && (best == nil || score > bestScore) {
			best = plan
			bestScore = score
		}
	}

	if best == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}
	return best, nil
}

func (r *candidateRouter) fallbackRoute(
	remaining lnwire.MilliSatoshi) (*route.Route, error) {

	if remaining <= 1 {
		return nil, errors.New("no smaller shard available")
	}

	values := make([]lnwire.MilliSatoshi, 0, 20)
	seen := make(map[lnwire.MilliSatoshi]bool)
	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - 1

	for _, pair := range [][2]int64{
		{3, 4}, {2, 3}, {3, 5}, {1, 2}, {2, 5},
		{1, 3}, {1, 4}, {1, 6}, {1, 8}, {1, 12},
	} {
		candidateAddAmount(
			&values, seen,
			remaining*lnwire.MilliSatoshi(pair[0])/
				lnwire.MilliSatoshi(pair[1]),
			minimum, maximum,
		)
	}

	if r.lastFailed > 0 {
		for _, pair := range [][2]int64{
			{3, 5}, {1, 2}, {2, 5}, {1, 3}, {1, 4}, {1, 6},
		} {
			candidateAddAmount(
				&values, seen,
				r.lastFailed*lnwire.MilliSatoshi(pair[0])/
					lnwire.MilliSatoshi(pair[1]),
				minimum, maximum,
			)
		}
	}

	sort.SliceStable(values, func(i, j int) bool {
		return values[i] > values[j]
	})

	var best *route.Route
	bestUtility := math.Inf(-1)

	for _, amount := range values {
		for _, option := range r.routeOptions(amount, 4) {
			fraction := float64(amount) / float64(remaining)
			fee := option.route.TotalAmount -
				candidateFinalAmount(option.route)
			utility := option.logProb +
				1.45*math.Log(fraction) -
				float64(fee)/4_000_000

			if utility > bestUtility {
				bestUtility = utility
				best = option.route
			}
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) routeFits(rt *route.Route) bool {
	added := make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil || r.policyBlocked[key] {
			return false
		}

		amount, ok := candidateRouteAmount(rt, i)
		if !ok || !edge.allows(amount) {
			return false
		}

		added[key] += amount
		total := r.reserved[key] + added[key]
		if total > edge.capacity {
			return false
		}

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok || total > balance {
				return false
			}
		}

		if failure, ok := r.failures[key]; ok &&
			failure.upper > 0 && total >= failure.upper {

			return false
		}
	}
	return true
}

func (r *candidateRouter) recordUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.limit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt && r.routeFits(rt) {
			r.planned = r.planned[1:]
			r.recordUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, planErr := r.makePlan(amt, partsLeft)
	if planErr == nil && len(plan) > 0 {
		rt := plan[0]
		if len(plan) > 1 {
			r.planned = append([]*route.Route(nil), plan[1:]...)
		} else {
			r.planned = nil
		}

		r.recordUse(rt)
		r.attempts++
		return rt, nil
	}

	rt, fallbackErr := r.fallbackRoute(amt)
	if fallbackErr != nil {
		if planErr != nil {
			return nil, planErr
		}
		return nil, fallbackErr
	}

	r.planned = nil
	r.recordUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	if failure, ok := r.failures[key]; ok &&
		failure.upper > 0 && amount >= failure.upper {

		delete(r.failures, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amount > belief.lowerOK {
		belief.lowerOK = amount
	}
	if belief.upperFail > 0 && amount >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amount
	if edge := r.edges[key]; edge != nil {
		high := edge.capacity * 17 / 20
		if high > estimate {
			estimate = high
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	current := r.failures[key]
	if current.upper == 0 || amount < current.upper {
		current.upper = amount
	}
	current.count++
	r.failures[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amount < belief.upperFail {
		belief.upperFail = amount
	}
	if belief.lowerOK >= amount {
		belief.lowerOK = 0
	}

	estimate := amount / 4
	if edge := r.edges[key]; edge != nil {
		low := edge.capacity / 20
		if estimate > low {
			estimate = low
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amount ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markSuspect(rt *route.Route, weight uint32) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if ok {
				r.learnSuccess(key, amount+r.reserved[key])
			}
		}

		r.held = append(r.held, rt)
		r.lastFailed = 0
		return nil
	}

	r.planned = nil
	r.lastFailed = candidateFinalAmount(rt)

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markSuspect(rt, 1)
		return nil
	}

	passed := failureIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markSuspect(rt, 1)
		return nil
	}
	amount, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markSuspect(rt, 1)
		return nil
	}

	total := amount + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, total)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

var _ routing.SimRouter = (*candidateRouter)(nil)

func (r *candidateRouter) String() string {
	return fmt.Sprintf("candidate-router(%x)", r.source[:4])
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const candidateFinalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))

	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts) + 12
	if r.attemptLimit < 16 {
		r.attemptLimit = 16
	}
	if r.attemptLimit > 36 {
		r.attemptLimit = 36
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		if r.edges[key] != nil {
			r.beliefs[key] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if amt <= 0 || capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.050)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.033))
	p := 0.47*lowMode + 0.53*highMode

	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity ||
		r.policyBlocked[edge.key] {

		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case failure.count >= 3 && ratio > 0.34:
			return 0
		case failure.count >= 2 && ratio > 0.50:
			return 0
		case ratio > 0.76:
			return 0
		case ratio > 0.62:
			retryScale = 0.13
		case ratio > 0.48:
			retryScale = 0.30
		case ratio > 0.32:
			retryScale = 0.57
		default:
			retryScale = 0.84
		}
		if failure.count >= 2 {
			retryScale *= 0.68
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.996

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.002

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		evidence := 0.996 - 0.993*position
		p = 0.08*p + 0.92*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		switch {
		case ratio >= 0.80:
			p *= 0.04
		case ratio >= 0.60:
			p *= 0.13
		case ratio >= 0.42:
			p *= 0.32
		case ratio >= 0.25:
			p *= 0.60
		}

	case belief.lowerOK > 0:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		if distance > 0 {
			boost := 0.66 * math.Exp(-distance/0.17)
			p += boost * (1 - p)
		}
	}

	if belief.estimate > 0 {
		scale := 0.065 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateP := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))

		weight := 0.14
		evidence := belief.successes + belief.failures
		if evidence >= 2 {
			weight = 0.23
		}
		if evidence >= 4 {
			weight = 0.32
		}
		p = (1-weight)*p + weight*estimateP
	}

	p *= retryScale
	switch {
	case p < 0.001:
		return 0.001
	case p > 0.997:
		return 0.997
	default:
		return p
	}
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	totalP := r.liquidityProbability(edge, reserved+amt)
	if totalP <= 0 {
		return 0
	}
	if reserved == 0 {
		return totalP
	}

	baseP := r.liquidityProbability(edge, reserved)
	if baseP <= 0 {
		return 0
	}

	p := totalP / baseP
	switch {
	case p < 0.001:
		return 0.001
	case p > 0.997:
		return 0.997
	default:
		return p
	}
}

type candidatePathLabel struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	edge     *candidateEdge
	next     *candidatePathLabel
	hops     int
	active   bool
	index    int
}

type candidatePathQueue []*candidatePathLabel

func (q candidatePathQueue) Len() int {
	return len(q)
}

func (q candidatePathQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidatePathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidatePathQueue) Push(value any) {
	label := value.(*candidatePathLabel)
	label.index = len(*q)
	*q = append(*q, label)
}

func (q *candidatePathQueue) Pop() any {
	old := *q
	last := len(old) - 1
	label := old[last]
	*q = old[:last]
	return label
}

func candidatePathContains(label *candidatePathLabel,
	node route.Vertex) bool {

	for current := label; current != nil; current = current.next {
		if current.node == node {
			return true
		}
	}
	return false
}

func candidateInsertLabel(labels map[route.Vertex][]*candidatePathLabel,
	label *candidatePathLabel) bool {

	current := labels[label.node]
	for _, old := range current {
		if old.active && old.score <= label.score &&
			old.required <= label.required {

			return false
		}
	}

	kept := current[:0]
	for _, old := range current {
		if old.active && label.score <= old.score &&
			label.required <= old.required {

			old.active = false
			continue
		}
		if old.active {
			kept = append(kept, old)
		}
	}
	kept = append(kept, label)

	if len(kept) > 4 {
		sort.Slice(kept, func(i, j int) bool {
			left := kept[i].score +
				float64(kept[i].required)/20_000_000
			right := kept[j].score +
				float64(kept[j].required)/20_000_000
			return left < right
		})
		for _, old := range kept[4:] {
			old.active = false
		}
		kept = kept[:4]
	}

	labels[label.node] = kept
	return label.active
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 920_000.0
		hopPenalty = 42_000.0
		maxHops    = 30
		maxExpand  = 16000
	)

	target := &candidatePathLabel{
		node:     r.spec.Target,
		required: amt,
		active:   true,
	}
	labels := map[route.Vertex][]*candidatePathLabel{
		r.spec.Target: {target},
	}
	queue := &candidatePathQueue{}
	heap.Push(queue, target)

	var sourceLabel *candidatePathLabel
	expanded := 0

	for queue.Len() != 0 && expanded < maxExpand {
		item := heap.Pop(queue).(*candidatePathLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			sourceLabel = item
			break
		}
		if item.hops >= maxHops {
			continue
		}

		expanded++
		for _, edge := range r.incomingEdges[item.node] {
			if candidatePathContains(item, edge.key.from) {
				continue
			}

			amountOverEdge := item.required
			p := r.probability(edge, amountOverEdge)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			required := amountOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.suspect[edge.key]) * 440_000
			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}

			label := &candidatePathLabel{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: required,
				logProb:  item.logProb + math.Log(p),
				edge:     edge,
				next:     item,
				hops:     item.hops + 1,
				active:   true,
			}
			if candidateInsertLabel(labels, label) {
				heap.Push(queue, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, sourceLabel.hops)
	for current := sourceLabel; current != nil && current.edge != nil;
		current = current.next {

		path = append(path, current.edge)
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLabel.logProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	node := r.source
	for _, edge := range path {
		if edge.key.from != node {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, errors.New("path does not reach target")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(candidateFinalCltvDelta)
		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, index int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return 0, false
	}
	if index == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[index-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	if rt == nil {
		return
	}
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	for _, rt := range r.held[len(r.held)-count:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, minimum,
	maximum lnwire.MilliSatoshi) {

	if maximum < minimum {
		return
	}
	if value < minimum {
		value = minimum
	}
	if value > maximum {
		value = maximum
	}
	if value <= 0 || seen[value] {
		return
	}

	seen[value] = true
	*values = append(*values, value)
}

func (r *candidateRouter) shardAnchors(
	avg lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	anchors := make([]lnwire.MilliSatoshi, 0, 32)

	for key, edge := range r.edges {
		endpoint := edge.key.from == r.source ||
			edge.key.to == r.spec.Target
		belief, learned := r.beliefs[key]
		if !endpoint && !learned {
			continue
		}

		reserved := r.reserved[key]
		limit := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}
		if edge.key.from == r.source {
			if balance, ok := r.localBalances[key.chanID]; ok &&
				balance < limit {

				limit = balance
			}
		}
		if limit > reserved {
			anchors = append(
				anchors, (limit-reserved)*9/10,
			)
		}

		if failure, ok := r.currentFails[key]; ok &&
			failure.upper > reserved {

			anchors = append(
				anchors, (failure.upper-reserved)*9/20,
			)
		}
		if belief.lowerOK > reserved {
			anchors = append(
				anchors, (belief.lowerOK-reserved)*19/20,
			)
		}
		if belief.upperFail > reserved {
			anchors = append(
				anchors, (belief.upperFail-reserved)*9/20,
			)
		}
		if belief.estimate > reserved {
			anchors = append(
				anchors, (belief.estimate-reserved)*4/5,
			)
		}
	}

	sort.Slice(anchors, func(i, j int) bool {
		if anchors[i] <= 0 {
			return false
		}
		if anchors[j] <= 0 {
			return true
		}
		left := math.Abs(math.Log(
			float64(anchors[i]) / float64(avg),
		))
		right := math.Abs(math.Log(
			float64(anchors[j]) / float64(avg),
		))
		return left < right
	})
	if len(anchors) > 5 {
		anchors = anchors[:5]
	}
	return anchors
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots int) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	minimum := lnwire.MilliSatoshi(1)
	maximum := remaining - lnwire.MilliSatoshi(slots-1)
	if maximum < minimum {
		return nil
	}

	avg := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	values := make([]lnwire.MilliSatoshi, 0, 14)
	seen := make(map[lnwire.MilliSatoshi]bool)

	for _, value := range []lnwire.MilliSatoshi{
		avg / 3,
		avg / 2,
		avg * 2 / 3,
		avg,
		avg * 4 / 3,
		avg * 3 / 2,
		avg * 2,
	} {
		candidateAddAmount(
			&values, seen, value, minimum, maximum,
		)
	}

	if r.lastFailedShard > 0 {
		for _, value := range []lnwire.MilliSatoshi{
			r.lastFailedShard / 3,
			r.lastFailedShard * 9 / 20,
			r.lastFailedShard * 3 / 5,
		} {
			candidateAddAmount(
				&values, seen, value, minimum, maximum,
			)
		}
	}

	for _, value := range r.shardAnchors(avg) {
		candidateAddAmount(
			&values, seen, value, minimum, maximum,
		)
	}

	return values
}

func candidateSharedPenalty(routes []*route.Route) map[candidateEdgeKey]float64 {
	penalties := make(map[candidateEdgeKey]float64)
	for _, rt := range routes {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}

			switch {
			case key.from == rt.SourcePubKey:
				penalties[key] += 600_000
			case key.to == rt.Hops[len(rt.Hops)-1].PubKeyBytes:
				penalties[key] += 2_000_000
			default:
				penalties[key] += 2_700_000
			}
		}
	}
	return penalties
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations, base map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	score := 0.0
	for key, total := range reservations {
		old := base[key]
		if total <= old {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, total)
		if p <= 0 {
			return math.Inf(-1)
		}
		if old > 0 {
			oldP := r.liquidityProbability(edge, old)
			if oldP <= 0 {
				return math.Inf(-1)
			}
			p /= oldP
		}

		if p < 0.001 {
			p = 0.001
		}
		if p > 0.999 {
			p = 0.999
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	uses := make(map[candidateEdgeKey]uint32)
	for _, rt := range routes {
		finalAmount := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmount {
			fees += rt.TotalAmount - finalAmount
		}
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			uses[key]++
			score -= 0.035 * float64(r.suspect[key])
		}
	}

	score -= float64(fees) / 25_000_000
	if len(routes) > 1 {
		score -= 0.025 * float64(len(routes)-1)
	}
	for key, count := range uses {
		if count <= 1 {
			continue
		}
		if key.from == r.source {
			score -= 0.045 * float64(count-1)
		} else {
			score -= 0.16 * float64(count-1)
		}
	}

	return score
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planWithParts(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	const beamWidth = 3

	base := candidateCopyReservations(r.reserved)
	saved := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = saved
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(base),
	}}

	for depth := 0; depth < parts; depth++ {
		slots := parts - depth
		expanded := make([]candidatePlanState, 0, beamWidth*12)

		for _, state := range states {
			r.reserved = candidateCopyReservations(
				state.reservations,
			)
			sizes := r.shardSizes(state.remaining, slots)
			penalty := candidateSharedPenalty(state.routes)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				remaining := state.remaining - size
				if slots == 1 && remaining != 0 {
					continue
				}
				if slots > 1 &&
					remaining < lnwire.MilliSatoshi(slots-1) {

					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				rt, _, err := r.findRoute(size, penalty)
				if err != nil {
					continue
				}

				reservations := candidateCopyReservations(
					state.reservations,
				)
				candidateReserveInto(reservations, rt)

				routes := append(
					append([]*route.Route(nil), state.routes...),
					rt,
				)
				score := r.planScore(routes, reservations, base)
				if math.IsInf(score, -1) {
					continue
				}

				expanded = append(expanded, candidatePlanState{
					remaining:    remaining,
					routes:       routes,
					reservations: reservations,
					score:        score,
				})
			}
		}

		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.Slice(expanded, func(i, j int) bool {
			if expanded[i].score == expanded[j].score {
				return expanded[i].remaining <
					expanded[j].remaining
			}
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	for _, state := range states {
		if state.remaining == 0 {
			return state.routes, state.score, true
		}
	}

	return nil, 0, false
}

func candidatePartCounts(maxParts int) []int {
	if maxParts < 2 {
		return nil
	}

	seen := make(map[int]bool)
	counts := make([]int, 0, 5)
	add := func(count int) {
		if count >= 2 && count <= maxParts && !seen[count] {
			seen[count] = true
			counts = append(counts, count)
		}
	}

	add(2)
	add(3)
	add(4)
	add(6)

	largest := maxParts
	if largest > 8 {
		largest = 8
	}
	add(largest)

	sort.Ints(counts)
	return counts
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	fullRoute, fullLogProb, fullErr := r.findRoute(total, nil)
	if parts == 1 {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{fullRoute}, nil
	}

	if fullErr == nil && fullLogProb >= math.Log(0.985) &&
		r.lastFailedShard == 0 {

		return []*route.Route{fullRoute}, nil
	}

	base := candidateCopyReservations(r.reserved)
	var best []*route.Route
	bestScore := math.Inf(-1)

	if fullErr == nil {
		reservations := candidateCopyReservations(base)
		candidateReserveInto(reservations, fullRoute)
		best = []*route.Route{fullRoute}
		bestScore = r.planScore(best, reservations, base)
	}

	for _, count := range candidatePartCounts(int(parts)) {
		plan, score, ok := r.planWithParts(total, count)
		if !ok {
			continue
		}
		if best == nil || score > bestScore {
			best = plan
			bestScore = score
		}
	}

	if best == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{fullRoute}, nil
	}

	return best, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) != 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt {
			r.planned = r.planned[1:]
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}
	if len(plan) == 0 {
		return nil, errors.New("empty route plan")
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil && edge.capacity > 0 {
		ratio := float64(amt) / float64(edge.capacity)
		switch {
		case ratio >= 0.08:
			estimate = edge.capacity * 7 / 8
		case ratio >= 0.035:
			estimate = edge.capacity * 3 / 4
		default:
			estimate = amt * 2
		}
		if estimate > edge.capacity {
			estimate = edge.capacity
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt / 3
	if edge := r.edges[key]; edge != nil {
		lowEstimate := edge.capacity / 18
		if estimate > lowEstimate {
			estimate = lowEstimate
		}
	}
	if estimate <= 0 {
		estimate = 1
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	if rt == nil {
		return
	}
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}

			r.learnSuccess(key, amount+r.reserved[key])
			if r.suspect[key] > 0 {
				r.suspect[key]--
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteSuspect(rt, 6)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failureIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 3)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 3)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amount, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 3)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amount + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 8
		r.lastFailedShard = candidateFinalAmount(rt)

	default:
		r.suspect[key] += 5
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}
